package agent

import (
	"context"
	"encoding/json"
	"iter"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/artex/sidequestion"
	"github.com/Autumn-27/norma/llm"
	"github.com/Autumn-27/norma/transcript"
)

type sideAgentProvider struct {
	calls int
	path  string
}

func (p *sideAgentProvider) Stream(ctx context.Context, req llm.CompletionRequest) iter.Seq2[llm.StreamEvent, error] {
	return func(y func(llm.StreamEvent, error) bool) {
		msg, stop, _, err := p.Complete(ctx, req)
		if err != nil {
			y(llm.StreamEvent{}, err)
			return
		}
		for _, b := range msg.Content {
			if b.Type == llm.BlockToolUse {
				if !y(llm.StreamEvent{Type: llm.SEToolUseStart, ToolID: b.ID, ToolName: b.Name}, nil) {
					return
				}
				if !y(llm.StreamEvent{Type: llm.SEToolInputJSON, Text: string(b.Input)}, nil) {
					return
				}
			} else if !y(llm.StreamEvent{Type: llm.SETextDelta, Text: b.Text}, nil) {
				return
			}
		}
		if !y(llm.StreamEvent{Type: llm.SEMessageDelta, StopReason: stop}, nil) {
			return
		}
		y(llm.StreamEvent{Type: llm.SEMessageStop}, nil)
	}
}
func (p *sideAgentProvider) Complete(_ context.Context, req llm.CompletionRequest) (llm.Message, string, llm.Usage, error) {
	p.calls++
	if p.calls == 1 {
		input, _ := json.Marshal(map[string]string{"file_path": p.path})
		return llm.Message{Role: llm.RoleAssistant, Content: []llm.ContentBlock{{Type: llm.BlockToolUse, ID: "fixture-read", Name: "Read", Input: input}}}, "tool_use", llm.Usage{}, nil
	}
	return llm.Message{Role: llm.RoleAssistant, Content: []llm.ContentBlock{llm.TextBlock("main finished")}}, "end_turn", llm.Usage{}, nil
}

func TestSideActualChatCheckpointToolResultAndTranscriptIsolation(t *testing.T) {
	for _, streaming := range []bool{false, true} {
		t.Run(map[bool]string{true: "stream", false: "atomic"}[streaming], func(t *testing.T) {
			dir := t.TempDir()
			file := filepath.Join(dir, "asset.txt")
			if err := os.WriteFile(file, []byte("controlled-homepage-result"), 0600); err != nil {
				t.Fatal(err)
			}
			p := &sideAgentProvider{path: file}
			bound := sidequestion.Bind(p, sidequestion.Model{Model: "fixture", Streaming: streaming})
			store := transcript.NewStore(filepath.Join(dir, "transcripts"))
			chat := NewChatAgent(bound, "fixture", dir, store, 100000)
			chat.SetNonStreaming(func() bool { return !streaming })
			var snapshots []sidequestion.Snapshot
			var activities []db.Activity
			ctx := sidequestion.WithPublisher(t.Context(), func(s sidequestion.Snapshot) { snapshots = append(snapshots, s) })
			if _, err := chat.Chat(ctx, "mainagent", "conv-987654", "Read the local fixture", 5, time.Minute, false, func(a db.Activity) { activities = append(activities, a) }); err != nil {
				t.Fatal(err)
			}
			if len(snapshots) < 3 {
				t.Fatalf("actual Chat missed capture hooks: %d", len(snapshots))
			}
			last := snapshots[len(snapshots)-1]
			raw, _ := json.Marshal(last)
			if last.Parent.ConversationID != 987654 || !strings.Contains(string(raw), "controlled-homepage-result") || !strings.Contains(string(raw), "main finished") {
				t.Fatalf("missing real tool result/final reply: %s", raw)
			}
			before, err := os.ReadFile(store.MainPath("conv-987654"))
			if err != nil {
				t.Fatal(err)
			}
			count := len(activities)
			tools := 0
			for _, a := range activities {
				if a.Kind == "tool_use" {
					tools++
				}
			}
			if tools != 1 {
				t.Fatalf("main fixture tool executions: %d", tools)
			}
			req, err := sidequestion.BuildRequest(last, nil, "side-only-question")
			if err != nil {
				t.Fatal(err)
			}
			// Reset the fake to request another Read; the side executor cannot run it.
			p.calls = 0
			p.path = filepath.Join(dir, "nonexistent")
			answer, err := (sidequestion.SideQuestionService{Provider: bound}).Answer(t.Context(), req, streaming, nil)
			if err != nil || !answer.ToolUse || p.calls != 1 || !strings.Contains(answer.Text, "不能执行工具") {
				t.Fatalf("tool denial %+v %v", answer, err)
			}
			after, err := os.ReadFile(store.MainPath("conv-987654"))
			if err != nil {
				t.Fatal(err)
			}
			if string(before) != string(after) || len(activities) != count {
				t.Fatal("side question modified main transcript/activity")
			}
			if len(snapshots) == 0 || snapshots[len(snapshots)-1].Version != last.Version {
				t.Fatal("side request replaced main checkpoint")
			}
		})
	}
}

source/agent/native_executor_config.go:
package agent

import (
	"io"
	"os"
	"path/filepath"
	"syscall"
	"time"

	"github.com/Autumn-27/artex/nativeexec"
	"github.com/Autumn-27/norma/llm"
)

// NativeWorkerExecutor accepts only the opaque provider produced by private
// runtime admission. No model, API, DB profile or environment chooses a path.
func NativeWorkerExecutor(provider llm.Provider) (nativeexec.Executor, error) {
	p, ok := provider.(*nativeRPC)
	if !ok || !p.appAdmission || p.policy.runtimeDir == "" || p.policy.phase == nil {
		return nil, nativeErr
	}
	hasWorker := false
	for _, role := range p.policy.phase.Roles {
		if role.Role == "worker" {
			hasWorker = true
		}
	}
	if !hasWorker {
		return nil, nativeErr
	}
	return loadNativeExecutor(p.policy.runtimeDir, p.policy.phase, syscall.Openat)
}

func loadNativeExecutor(dir string, phase *nativePhasePermit, openAt func(int, string, int, uint32) (int, error)) (nativeexec.Executor, error) {
	if phase == nil || phase.state == nil || !time.Now().Before(phase.ExpiresAt) {
		return nil, nativeErr
	}
	phase.state.mu.Lock()
	stopped := phase.state.stopped
	phase.state.mu.Unlock()
	if stopped {
		return nil, nativeErr
	}
	fd, e := syscall.Open(dir, syscall.O_RDONLY|syscall.O_DIRECTORY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0)
	if e != nil {
		return nil, nativeErr
	}
	defer syscall.Close(fd)
	var st syscall.Stat_t
	if syscall.Fstat(fd, &st) != nil || (st.Uid != 0 && st.Uid != uint32(os.Geteuid())) || st.Mode&0777 != 0700 {
		return nil, nativeErr
	}
	read := func(name string, max int64) ([]byte, error) {
		n, e := openAt(fd, name, syscall.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK|syscall.O_CLOEXEC, 0)
		if e != nil {
			return nil, nativeErr
		}
		f := os.NewFile(uintptr(n), name)
		defer f.Close()
		i, e := f.Stat()
		if e != nil || !i.Mode().IsRegular() {
			return nil, nativeErr
		}
		st, ok := i.Sys().(*syscall.Stat_t)
		if !ok || !privateNativeOwner(st.Uid, i.Mode()) || st.Nlink != 1 {
			return nil, nativeErr
		}
		b, e := io.ReadAll(io.LimitReader(f, max+1))
		if e != nil || int64(len(b)) > max {
			return nil, nativeErr
		}
		return b, nil
	}
	raw, e := read("executor.json", 4096)
	if e != nil {
		return nil, nativeErr
	}
	var c struct {
		SchemaVersion   int    `json:"schema_version"`
		Reviewed        bool   `json:"reviewed"`
		PhaseID         string `json:"phase_id"`
		Generation      int64  `json:"authority_generation"`
		TaskID          int64  `json:"task_id"`
		ExplorationID   int64  `json:"exploration_id"`
		ExecutorID      string `json:"executor_id"`
		NetworkPolicyID string `json:"network_policy_id"`
		FixtureOrigin   string `json:"fixture_origin"`
		ControlSocket   string `json:"control_socket"`
	}
	if strictNativeJSON(raw, &c) != nil || c.SchemaVersion != 1 || !c.Reviewed || c.PhaseID != phase.PhaseID || c.Generation != phase.Generation || c.TaskID != phase.TaskID || c.ExplorationID != phase.ExplorationID || c.ExecutorID != phase.ExecutorID || c.NetworkPolicyID != phase.NetworkPolicyID || c.FixtureOrigin != phase.FixtureOrigin || !filepath.IsAbs(c.ControlSocket) || filepath.Clean(c.ControlSocket) != c.ControlSocket || len(c.ControlSocket) > 107 {
		return nil, nativeErr
	}
	// All nonsecret identity/configuration checks precede even opening the key.
	key, e := read("executor.key", 32)
	if e != nil || len(key) != 32 {
		return nil, nativeErr
	}
	return nativeexec.NewClient(c.ControlSocket, key)
}

source/agent/wrapup.go:
package agent

import (
	"strings"

	"github.com/Autumn-27/norma/harness"
)

// The SDK injects the wrap-up/settlement prompt when the agent exhausts its
// turn budget (MaxTurns) or times out (run_seconds/MaxDuration), so it persists
// identified but unsaved results and ends with a one-sentence summary.
//
// Admins can override each agent wrap-up prompt in agents.wrapup_prompt; empty
// uses the built-in default. Only prompt text is editable here; disabled tools
// and settlement budget policy are controlled by code.

// WrapupOverride, if set, returns the stored wrap-up prompt for an agent key and
// whether a non-empty one exists. Wired by the server to the agents table (like
// PromptOverride for system prompts). nil / empty → the built-in default is used.
var WrapupOverride func(agentKey string) (string, bool)

// WrapupMaxTurnsOverride, if set, returns the admin-configured turn budget for the
// wrap-up phase of an agent and whether a positive one exists. Wired to the agents
// table. nil / ≤0 → the built-in per-agent default (wrapupTurnDefaults) is used.
var WrapupMaxTurnsOverride func(agentKey string) (int, bool)

// Built-in wrap-up prompts by agent key. Workers reuse settleWrapUpPrompt in
// worker.go; planner/mainagent have their own. Unknown/custom keys use a generic fallback.
var wrapupDefaults = map[string]string{
	"worker":    settleWrapUpPrompt,
	"planner":   plannerWrapUpDefault,
	"mainagent": mainAgentWrapUpDefault,
}

// wrapupTurnDefaults gives each settlement phase its own turn budget (positive
// admin values override it). All get 10 turns to persist results; unknown keys
// use genericWrapupTurns.
var wrapupTurnDefaults = map[string]int{
	"worker":    10,
	"planner":   10,
	"mainagent": 10,
}

const genericWrapupTurns = 10

const plannerWrapUpDefault = "Your turn budget for this planning round is nearly exhausted. Only THIS ROUND is ending: the system will wake you again as the situation changes; the task is not terminating, so do not wind down the entire planning process. Persist conclusions already reached this round, but DO NOT invent intents merely to wrap up (zero intents this round remains a valid outcome): (1) If you have identified directions that SHOULD BE DISPATCHED NOW, submit them in one batch with add_intent; do not withhold ready directions. (2) For goals already proven achieved by findings/facts, call prove_goal to mark met; do not miss them. (3) Record any multi-step serial exploitation chain with TodoWrite so you can dispatch its next step on a later wake-up. Then end this round without a summary."

const mainAgentWrapUpDefault = "Your turn budget is nearly exhausted and this interaction is ending. Do not start new exploration or operations. **In a separate single plain-text sentence**, summarize current progress, key conclusions, and the recommended next step for the user."

const genericWrapUpDefault = "You are about to be terminated because your budget is exhausted. First persist completed results that have not yet been saved, then **in a separate single plain-text sentence** summarize what you did and the key conclusions (this sentence will be displayed as the run result)."

// WrapupDefault returns the built-in default wrap-up prompt for an agent key —
// used by the admin UI as the "restore default" value and empty-field placeholder.
func WrapupDefault(agentKey string) string {
	if d, ok := wrapupDefaults[agentKey]; ok {
		return d
	}
	return genericWrapUpDefault
}

// WrapupTurnsDefault returns the built-in wrap-up turn budget for an agent key —
// used by the admin UI as the "0 = default N" hint.
func WrapupTurnsDefault(agentKey string) int {
	if n, ok := wrapupTurnDefaults[agentKey]; ok {
		return n
	}
	return genericWrapupTurns
}

// resolveWrapup returns the effective wrap-up prompt: the DB override (if set and
// non-empty) over the built-in default.
func resolveWrapup(agentKey string) string {
	if WrapupOverride != nil {
		if t, ok := WrapupOverride(agentKey); ok && strings.TrimSpace(t) != "" {
			return t
		}
	}
	return WrapupDefault(agentKey)
}

// resolveWrapupTurns returns the effective wrap-up turn budget: a positive DB
// override over the built-in per-agent default.
func resolveWrapupTurns(agentKey string) int {
	if WrapupMaxTurnsOverride != nil {
		if v, ok := WrapupMaxTurnsOverride(agentKey); ok && v > 0 {
			return v
		}
	}
	return WrapupTurnsDefault(agentKey)
}

// wrapupSettlement builds the settlement config for an agent's run. Prompt and the
// turn budget are admin-editable per agent; disabled tools are code-owned policy so
// a user can't edit away the "stop probing" guardrail. Resolved fresh each run
// (reads DB live), so edits apply on the next run without a restart.
func wrapupSettlement(agentKey string, disabledTools []string) *harness.Settlement {
	return &harness.Settlement{
		Prompt:        resolveWrapup(agentKey),
		DisabledTools: disabledTools,
		MaxTurns:      resolveWrapupTurns(agentKey),
	}
}

// ---------- Task-level timeout wrap-up (see docs/任务级超时与收尾设计.md) ----------
//
// Separate from per-run wrap-up: one run exhausting its budget does not mean
// the whole task is ending. Planner semantics differ: continue planning after
// a run, but stop dispatching and assess final goals at task timeout. Worker/planner only.

// WrapupTaskTimeoutOverride / ...TurnsOverride provide DB overrides for task
// timeout prompts and budgets (agents.task_timeout_wrapup_prompt / _max_turns; worker/planner only).
var (
	WrapupTaskTimeoutOverride      func(agentKey string) (string, bool)
	WrapupTaskTimeoutTurnsOverride func(agentKey string) (int, bool)
)

var taskTimeoutWrapupDefaults = map[string]string{
	"worker":  workerTaskTimeoutDefault,
	"planner": plannerTaskTimeoutDefault,
}

const workerTaskTimeoutDefault = "**The entire task has reached its timeout and is ending** (not merely this run's budget: the whole exploration has reached its deadline). This is your final opportunity: (1) Persist ALL identified but unsaved results: insert_assets for new assets, record_fact for exploration conclusions/facts, and report_finding for confirmed vulnerabilities. (2) Do not start any new commands or probes. (3) **End with a separate single plain-text sentence** summarizing your key conclusions for this intent."

const plannerTaskTimeoutDefault = "**The entire task has reached its timeout and is ending** (the whole task, not just this round). Make a final goal assessment using ALL current facts and findings: call prove_goal to mark met for goals proven achieved by evidence; do not miss any. **Do not generate any new intents** (they would no longer be executed). End after assessment without a summary."

// TaskTimeoutWrapupDefault returns the built-in task timeout prompt for admin placeholders/reset.
func TaskTimeoutWrapupDefault(agentKey string) string {
	return taskTimeoutWrapupDefaults[agentKey] // Empty for unconfigured mainagent/chat.
}

// resolveTaskTimeoutWrapup prefers nonempty DB overrides to built-ins. Empty
// means no task timeout prompt (not worker/planner); callers fall back to per-run.
func resolveTaskTimeoutWrapup(agentKey string) string {
	if WrapupTaskTimeoutOverride != nil {
		if t, ok := WrapupTaskTimeoutOverride(agentKey); ok && strings.TrimSpace(t) != "" {
			return t
		}
	}
	return TaskTimeoutWrapupDefault(agentKey)
}

func resolveTaskTimeoutTurns(agentKey string) int {
	if WrapupTaskTimeoutTurnsOverride != nil {
		if v, ok := WrapupTaskTimeoutTurnsOverride(agentKey); ok && v > 0 {
			return v
		}
	}
	return resolveWrapupTurns(agentKey) // Default to the per-run turn budget.
}

// wrapupSettlementForTask builds settlement for a worker/planner run that is aware
// of the task deadline. See §5 of the design doc:
//   - clamped=true: this run is bounded by the task deadline. Timeout means
//     task expiry; MaxTurns means turns ran out first, so use the per-run prompt.
//   - clamped=false: both reasons use the per-run prompt (wrapupSettlement).
//
// PromptByReason lets the harness select from the actual settlement reason, not a build-time guess.
func wrapupSettlementForTask(agentKey string, disabledTools []string, clamped bool) *harness.Settlement {
	perRun := resolveWrapup(agentKey)
	st := &harness.Settlement{
		Prompt:        perRun, // Fallback; both reasons use this when not clamped.
		DisabledTools: disabledTools,
		MaxTurns:      resolveWrapupTurns(agentKey),
	}
	if clamped {
		if tt := resolveTaskTimeoutWrapup(agentKey); tt != "" {
			st.PromptByReason = map[harness.TerminalReason]string{
				harness.ReasonTimeout:  tt,     // Task deadline reached.
				harness.ReasonMaxTurns: perRun, // Turns exhausted while task time remains.
			}
			st.MaxTurns = resolveTaskTimeoutTurns(agentKey)
		}
	}
	return st
}

source/agent/capture_usage_test.go:
package agent

import (
	"context"
	"errors"
	"iter"
	"testing"

	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/norma/agentcore"
	"github.com/Autumn-27/norma/llm"
)

type captureUsageProvider struct {
	stream func(context.Context, func(llm.StreamEvent, error) bool)
}

func (p captureUsageProvider) Stream(ctx context.Context, _ llm.CompletionRequest) iter.Seq2[llm.StreamEvent, error] {
	return func(yield func(llm.StreamEvent, error) bool) { p.stream(ctx, yield) }
}

func (p captureUsageProvider) Complete(ctx context.Context, req llm.CompletionRequest) (llm.Message, string, llm.Usage, error) {
	acc := llm.NewAccumulator()
	for ev, err := range p.Stream(ctx, req) {
		if err != nil {
			return llm.Message{}, "", llm.Usage{}, err
		}
		acc.Add(ev)
	}
	return acc.Message(), acc.StopReason, acc.Usage, nil
}

func TestCaptureRunPersistsUsageOnProviderFailure(t *testing.T) {
	wantErr := errors.New("provider failed after reporting usage")
	provider := captureUsageProvider{stream: func(_ context.Context, yield func(llm.StreamEvent, error) bool) {
		// 遵守迭代器协议:yield 返回 false 后立即停止,不再调用它。
		if !yield(llm.StreamEvent{Type: llm.SEMessageStart, Usage: llm.Usage{InputTokens: 11, CacheReadTokens: 3}}, nil) {
			return
		}
		if !yield(llm.StreamEvent{Type: llm.SETextDelta, Text: "partial"}, nil) {
			return
		}
		if !yield(llm.StreamEvent{Type: llm.SEMessageDelta, Usage: llm.Usage{OutputTokens: 7, CacheWriteTokens: 2}}, nil) {
			return
		}
		yield(llm.StreamEvent{}, wantErr)
	}}

	var activities []db.Activity
	_, _, err := captureRun(context.Background(), agentcore.Options{Provider: provider, MaxTurns: 1}, "test", func(a db.Activity) {
		activities = append(activities, a)
	})
	if !errors.Is(err, wantErr) {
		t.Fatalf("captureRun error=%v, want %v", err, wantErr)
	}
	assertCapturedResultUsage(t, activities, 11, 7, 3, 2)
}

func TestCaptureRunPersistsUsageOnCancellation(t *testing.T) {
	started := make(chan struct{})
	provider := captureUsageProvider{stream: func(ctx context.Context, yield func(llm.StreamEvent, error) bool) {
		// 遵守迭代器协议:yield 返回 false 后立即停止,不再调用它。
		if !yield(llm.StreamEvent{Type: llm.SEMessageStart, Usage: llm.Usage{InputTokens: 13, CacheReadTokens: 5}}, nil) {
			return
		}
		if !yield(llm.StreamEvent{Type: llm.SETextDelta, Text: "partial"}, nil) {
			return
		}
		if !yield(llm.StreamEvent{Type: llm.SEMessageDelta, Usage: llm.Usage{OutputTokens: 9, CacheWriteTokens: 4}}, nil) {
			return
		}
		close(started)
		<-ctx.Done()
		yield(llm.StreamEvent{}, ctx.Err())
	}}

	ctx, cancel := context.WithCancel(context.Background())
	var activities []db.Activity
	done := make(chan error, 1)
	go func() {
		_, _, err := captureRun(ctx, agentcore.Options{Provider: provider, MaxTurns: 1}, "test", func(a db.Activity) {
			activities = append(activities, a)
		})
		done <- err
	}()
	<-started
	cancel()
	if err := <-done; !errors.Is(err, context.Canceled) {
		t.Fatalf("captureRun error=%v, want context canceled", err)
	}
	assertCapturedResultUsage(t, activities, 13, 9, 5, 4)
}

func assertCapturedResultUsage(t *testing.T, activities []db.Activity, input, output, read, write int) {
	t.Helper()
	results := 0
	for _, activity := range activities {
		if activity.Kind != "result" {
			continue
		}
		results++
		if activity.InputTokens == nil || *activity.InputTokens != input ||
			activity.OutputTokens == nil || *activity.OutputTokens != output ||
			activity.CacheReadTokens == nil || *activity.CacheReadTokens != read ||
			activity.CacheWriteTokens == nil || *activity.CacheWriteTokens != write {
			t.Fatalf("result usage=%+v, want input=%d output=%d read=%d write=%d", activity, input, output, read, write)
		}
	}
	if results != 1 {
		t.Fatalf("result activity count=%d, activities=%+v", results, activities)
	}
}

source/agent/runinfo.go:
package agent

import (
	"context"

	"github.com/Autumn-27/artex/db"
)

// RunInfo identifies WHICH run a tool call belongs to. Tool assembly only receives
// (ctx, agentKey) — the task/exploration ids live in the caller's arguments, not the
// ctx — so anything wired at assembly time (currently the Skill ledger in
// server/assembly.go) has no way to attribute a call to a task. Each run attaches
// its own RunInfo before calling AugmentTools; the wiring closure reads it once and
// captures it, so per-run attribution stays correct without threading parameters
// through the tool layer. Same pattern as TaskClock (see taskclock.go).
//
// Zero value = attribution unknown; every consumer must treat it as optional.
type RunInfo struct {
	TaskID        int64  // task registry id; 0 for non-task runs (chat sessions)
	ExplorationID int64  // exploration id; 0 when unknown
	IntentID      int64  // worker's intent node; 0 for planner/mainagent/chat
	SessionID     string // chat conversation id; empty for task runs
}

// explorationID reads a store's exploration id, tolerating a nil store (planner and
// worker runs can be driven without one in tests).
func explorationID(ts *db.ExplorationStore) int64 {
	if ts == nil {
		return 0
	}
	return ts.ID()
}

type runInfoKey struct{}

// WithRunInfo attaches run attribution to ctx.
func WithRunInfo(ctx context.Context, ri RunInfo) context.Context {
	return context.WithValue(ctx, runInfoKey{}, ri)
}

// RunInfoFrom reads the RunInfo (zero value if none attached).
func RunInfoFrom(ctx context.Context) RunInfo {
	if v, ok := ctx.Value(runInfoKey{}).(RunInfo); ok {
		return v
	}
	return RunInfo{}
}

//go:build artex_native_pg

package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"

	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/artex/nativeexec"
	"github.com/Autumn-27/norma/llm"
	actool "github.com/Autumn-27/norma/tool"
	"github.com/Autumn-27/norma/transcript"
)

// Explicit opt-in: no skip and no replacement database. The model transport is
// a labelled proposal spy, not a live assessment or claimed model observation.
func TestNativePlannerCreatesIntentThroughRealPlan(t *testing.T) {
	dsn := os.Getenv("ARTEX_TEST_PG_DSN")
	if dsn == "" {
		t.Fatal("UNEXECUTED: approved ARTEX_TEST_PG_DSN required")
	}
	d, err := db.Open(dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer d.Close()
	task, err := d.CreateTask("native domain tracer", "Review the authorized synthetic fixture for information disclosure", nil, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	defer d.DeleteTask(task.ID)
	ts := d.Exploration(task.ExplorationID)
	tool := NewToolSet(ts, "planner").addIntent()
	schema, _ := json.Marshal(tool.InputSchema())
	agents := json.RawMessage(`["planner"]`)
	if err = d.SeedTool(tool.Name(), tool.Description(), schema, agents); err != nil {
		t.Fatal(err)
	}
	oldA, oldR := ToolAugment, ToolResolve
	defer func() { ToolAugment = oldA; ToolResolve = oldR }()
	augmentCalls := 0
	ToolAugment = func(context.Context, string) ([]actool.CoreTool, DeferredInfo, func()) {
		augmentCalls++
		return nil, DeferredInfo{}, func() {}
	}
	// Exercise persisted enabled bindings and actual original handler/schema. The
	// production server resolver independently applies this same native-only gate.
	ToolResolve = func(_ context.Context, role string, base []actool.CoreTool) []actool.CoreTool {
		rows, e := d.ListTools()
		if e != nil {
			return []actool.CoreTool{}
		}
		out := []actool.CoreTool{}
		for _, candidate := range base {
			for _, row := range rows {
				if candidate.Name() != row.Key || row.Key != "add_intent" || !row.Enabled {
					continue
				}
				bound := false
				for _, r := range row.Agents {
					if r == role {
						bound = true
					}
				}
				if !bound {
					continue
				}
				var s map[string]any
				if json.Unmarshal(row.Schema, &s) != nil {
					return []actool.CoreTool{}
				}
				out = append(out, DecorateTool(candidate, row.Description, s))
			}
		}
		return out
	}
	resolved := ToolResolve(context.Background(), "planner", []actool.CoreTool{tool})
	if len(resolved) != 1 {
		t.Fatal("positive persisted planner binding unavailable")
	}
	plannerSchemas := actool.NewRegistry(resolved...).Schemas()
	workerSet := NewToolSet(ts, "worker")
	workerSet.SetTaskID(task.ID)
	workerTools := append([]actool.CoreTool{workerSet.recordFact()}, nativeexec.Six()...)
	workerSchemas := actool.NewRegistry(workerTools...).Schemas()
	dir, phase := rolePermitFixture(t)
	phase["task_id"] = task.ID
	phase["exploration_id"] = task.ExplorationID
	phase["roles"] = []any{
		map[string]any{"role": "planner", "purpose": "run", "intent_id": 0, "session_id": fmt.Sprintf("exp%d-planner", task.ExplorationID), "catalog_sha256": roleFixtureDigest(t, phase, "planner", plannerSchemas)},
		map[string]any{"role": "worker", "purpose": "run", "dynamic_intent": true, "intent_id": 0, "session_id": "", "catalog_sha256": roleFixtureDigest(t, phase, "worker", workerSchemas)},
	}
	writeRolePermit(t, dir, phase)
	policy, opens, err := loadRoleFixture(t, dir)
	if err != nil || opens != 1 {
		t.Fatalf("private permit: %v key_opens=%d", err, opens)
	}
	cfg := ConfigFrom("codex-native", "gpt-6.1-sol", policy.Endpoint, "", "")
	cfg.Native = policy
	p, err := newNativeRPC(cfg)
	if err != nil {
		t.Fatal(err)
	}
	p.appAdmission = true
	calls := 0
	p.client.Transport = roleRoundTrip(func(req *http.Request) (*http.Response, error) {
		calls++
		body := roleSyntheticResponse
		if calls == 1 {
			body = `{"protocol":"artex-native-v1","profile":"codex-native","generation_tokens_enforced":false,"message":{"role":"assistant","content":[{"type":"tool_use","id":"call_11111111111111111111111111111111","name":"add_intent","input":{"summary":"Inspect the authorized synthetic fixture for publicly exposed diagnostic information"}}]},"stop_reason":"tool_use","usage":{"input_tokens":1,"output_tokens":1,"cache_read_tokens":0,"cache_write_tokens":0}}`
		}
		return &http.Response{StatusCode: 200, Header: http.Header{"Content-Type": []string{"application/json"}}, Body: io.NopCloser(strings.NewReader(body))}, nil
	})
	pl := NewPlanner(p, "gpt-6.1-sol", t.TempDir(), nil, 0, 3)
	pl.SetNoaEnabled(func() bool { t.Fatal("native called NoA resolver"); return true })
	if _, _, err = pl.Plan(t.Context(), task.ID, nil, ts, task.Goal, nil, nil); err != nil {
		t.Fatal(err)
	}
	nodes, err := ts.ListByKind(db.KindIntent, 100)
	if err != nil || len(nodes) != 1 || calls != 2 || augmentCalls != 0 {
		t.Fatalf("persisted intents=%d provider_calls=%d mcp=%d err=%v", len(nodes), calls, augmentCalls, err)
	}
	intent := nodes[0]
	if intent.Origin != "planner" || !strings.Contains(string(intent.Payload), "publicly exposed diagnostic") {
		t.Fatalf("not the real planner proposal: %+v", intent)
	}
	claimed, err := ts.ClaimIntent(intent.ID, "native-tracer")
	if err != nil || !claimed {
		t.Fatalf("actual scheduler claim failed: %v", err)
	}
	ri := RunInfo{TaskID: task.ID, ExplorationID: task.ExplorationID, IntentID: intent.ID}
	ctx := transcript.WithSessionID(WithRunInfo(t.Context(), ri), WorkerSessionID(ts.ID(), intent.ID))
	if _, err = p.BindNativeRole(ctx, "worker", "run", ri, workerSchemas); err == nil {
		t.Fatal("template bound without DB boundary")
	}
	ctx, err = p.BindNativeTaskRole(ctx, "worker", ri, ts, workerSchemas)
	if err != nil {
		t.Fatal(err)
	}
	good := json.RawMessage(fmt.Sprintf(`{"intent_id":%d,"summary":"synthetic DB tracer fact; no target observations","confidence":"inferred"}`, intent.ID))
	if _, err = workerSet.recordFact().Call(ctx, good, nil); err != nil {
		t.Fatalf("positive real domain handler: %v", err)
	}
	bad := json.RawMessage(fmt.Sprintf(`{"intent_id":%d,"facts":[{"intent_id":%d,"summary":"must not persist"}]}`, intent.ID, intent.ID+1))
	if _, err = workerSet.recordFact().Call(ctx, bad, nil); err == nil {
		t.Fatal("nested worker ID drift admitted")
	}
	if err = ts.SetIntentState(intent.ID, "stopped"); err != nil {
		t.Fatal(err)
	}
	if _, err = resolveNativeExecution(ctx); err == nil {
		t.Fatal("stopped intent retained effect binding")
	}
	if _, _, _, err = p.Complete(ctx, llm.CompletionRequest{Messages: []llm.Message{llm.UserText("synthetic")}, Tools: workerSchemas}); err == nil || calls != 2 {
		t.Fatal("revoked DB membership reached provider")
	}
	t.Logf("REAL PG Plan persisted unknown intent %d; dynamic binding from template, final nested-ID denial, stopped-intent denial; synthetic provider only, no executor/E2E claim", intent.ID)
}

