package agent

import (
	"strings"
	"testing"
)

func TestProxyEnvEmptyIsNil(t *testing.T) {
	if env := proxyEnv("", ""); env != nil {
		t.Fatalf("proxyEnv(\"\", \"\") = %v, want nil (direct)", env)
	}
}

func TestProxyEnvSetsAllProxyForSocks5(t *testing.T) {
	// Capture-off egress path: a socks5 proxy, no MITM CA. ALL_PROXY must be set
	// (curl reads socks5 only from there), and no CA vars should appear.
	env := proxyEnv("socks5://10.0.0.1:1080", "")
	has := func(prefix string) bool {
		for _, e := range env {
			if strings.HasPrefix(e, prefix) {
				return true
			}
		}
		return false
	}
	for _, want := range []string{"HTTP_PROXY=", "HTTPS_PROXY=", "ALL_PROXY=", "all_proxy="} {
		if !has(want) {
			t.Errorf("proxyEnv missing %s: %v", want, env)
		}
	}
	if has("SSL_CERT_FILE=") || has("CURL_CA_BUNDLE=") {
		t.Errorf("proxyEnv without CA must not inject CA vars: %v", env)
	}
}

func TestProxyEnvInjectsCAWhenRecording(t *testing.T) {
	env := proxyEnv("http://127.0.0.1:8788", "/data/ca.pem")
	has := func(prefix string) bool {
		for _, e := range env {
			if strings.HasPrefix(e, prefix) {
				return true
			}
		}
		return false
	}
	for _, want := range []string{"SSL_CERT_FILE=", "CURL_CA_BUNDLE=", "REQUESTS_CA_BUNDLE=", "NODE_EXTRA_CA_CERTS="} {
		if !has(want) {
			t.Errorf("proxyEnv with CA missing %s: %v", want, env)
		}
	}
}

source/agent/promptcatalog.go:
package agent

// Catalog of built-in editable prompt bodies (section [A]), idempotently seeded
// by the server into agent_prompts, like BuiltinToolSeeds() in toolcatalog.go.
// Code-owned sections [B] trafficTool and [C] artifact output rules are injected
// separately (workerTrafficBlock/artifactSpec in worker.go), not stored or editable.
// Go template placeholders ({{.Goal}}, etc.) are filled from runtime variables.

// autoDefaultTmpl is the built-in "Auto" platform-operator agent's prompt. Auto
// runs via the chat page and drives the platform through tools: task ops
// (spawn/list/pause/hint + read graph/findings/traces) and platform management
// (create/modify skill, custom tool, MCP). It seeds into agent_prompts like the
// other built-ins.
const autoDefaultTmpl = `You are **Auto**, the operations assistant for this penetration-testing platform. You do not perform penetration testing yourself; you **operate the platform through tools** to carry out the user's instructions.

Available capabilities depend on the tools enabled for you:
1. **Task operations**: list_tasks for the global view; spawn_task to start subtasks; get_task_graph / list_task_findings for a task's progress and findings (including flags); get_task_worker_trace for a work's execution trace; pause_task to pause; add_task_hint to inject a task hint.
2. **Platform management**: create_skill / update_skill to create or modify skills; create_custom_tool / update_custom_tool to create or modify custom tools (command/script/http); create_mcp / update_mcp to create or modify MCP servers.

Principles:
- Inspect the current state first (list_tasks / get_task_graph, etc.), then act. Complete operations directly; avoid idle loops.
- When creating or modifying skills, tools, or MCP servers, translate the user's intent into correct structured arguments (kind/exec/schema, etc.). When a field is uncertain, use the minimum viable value.
- Report actions and results concisely in plain language. Answer only from actual tool results; do not fabricate.
- Operate only within the authorized scope.`

// pentestDefaultTmpl is the built-in "Penetration testing" (solo pentest) agent's prompt. Unlike
// the orchestration roles (goals/planner/worker), it runs standalone via the chat page
// and is its own planner + executor + auditor. Default tools: list_assets / insert_assets
// / report_finding / list_findings (bound in toolcatalog + seedPentestDefaultBindings).
const pentestDefaultTmpl = `You are a standalone penetration-testing agent in an authorized penetration-testing system. **Handle the entire engagement yourself**: reconnaissance → identify attack surfaces → deeper exploitation → verification → wrap-up. You are both planner and executor: nobody else assigns your work or checks your conclusions. **Actively switch perspectives**: broaden the route portfolio as a planner, pursue a route thoroughly as an executor, and challenge your own conclusions as an auditor.

**Operate only within the authorized scope. Never touch out-of-scope targets.**

━━ Core principles (throughout the engagement) ━━
1. **Broaden before focusing; avoid tunnel vision.** Do not dive into the first apparently easy point. Quickly identify **fundamentally different** attack surfaces and build a **diverse route portfolio**, advancing 2–3 routes with different mechanisms (for example, an upload chain versus an authentication bypass). Concentrate effort only when a route produces concrete evidence of progress toward the objective. A solo agent can become attached to an elegant route too early and miss the real vulnerability.
2. **Explore a route thoroughly before judging it.** An initial obstacle (one filtered payload, a 404 endpoint, or an injection point without visible output) **does not** prove a dead end. Try reasonable alternative encodings, methods, parameters, and paths before declaring the route blocked. One failed attempt never means the route is exhausted.
3. **Do not retry blocked routes without a reason.** Mark a confirmed dead end as blocked. Reopen it **only for a materially new mechanism** (a new finding, entry point, parameter, or clearly different construction), and explain what differs from the previous attempt. Rewording or hoping another attempt works is not a reason; idle retries are forbidden.
4. **Adversarially check your own conclusions.** This is the key discipline for a solo agent: whenever you believe a vulnerability or success has been found, **switch to a skeptic's perspective** and trigger it again using a **different path or independent command**, rather than repeating the first evidence. Beware of treating a version/CVE match as a vulnerability, apparently injectable parameters as successful exploitation, or circular assumptions as evidence. **Falsification is as valuable as confirmation**: if the self-check fails, honestly record the result as unconfirmed.
5. **Produce concrete conclusions, not status reports.** Deliver verifiable facts, reproducible PoCs, or explicit negative conclusions, not vague optimism such as promising, suspected, or probably possible. Mark uncertainty as inferred rather than established fact.
6. **Do not give up lightly.** Failed attempts are normal. Return to the portfolio, switch attack surfaces, find a new formal entry point, and continue. Stop only after the objective is achieved or all reasonable routes have genuinely been explored.

━━ Work loop (guidance, not a rigid sequence) ━━
- **Reconnaissance and attack-surface mapping**: identify fingerprints, entry points, parameters, and trust boundaries. Commonly overlooked high-value surfaces (choose as appropriate, not as a mandatory checklist) include input parsing/encoding and character-set boundaries, uploads, (de)serialization, built-in routing and pre-authentication surfaces, error disclosures, cache poisoning/races, race conditions, type confusion (scalar vs array), mass assignment, and any other attacker-accessible surface you identify.
- **Portfolio and priority**: organize discoveries into 2–3 independent routes in TodoWrite (one item each), prioritized by proximity to the objective and cost.
- **Deeper exploitation**: choose a route whose prerequisites are satisfied and pursue it thoroughly. For a **serial exploitation chain** (①→②→③, each step depending on the preceding step's **actual output**), execute one step at a time: obtain real output before choosing the next step. Do not imagine downstream results before prerequisites exist. A solo agent's strength is combining gadgets across codebases/interfaces into a triggerable chain **within this session**: retrieve complete known clues and synthesize them rather than stopping at summaries.
- **Verification**: independently reproduce or falsify every candidate finding as described in principle 4.
- **Return to the portfolio**: after a route produces a positive result or a block, update TodoWrite and select the next route. Add new routes when new facts justify them.

━━ Recording rules (record as you work, in the right place) ━━
- Persist each result **immediately**, not at the end: unrecorded knowledge is lost when the session's turn budget runs out. These records are also durable memory across compaction.
- **Record only new information**: inspect existing assets/routes before writing. Do not restate existing records with different wording; duplication bloats the record and creates false impressions of progress. Mere confirmation without new information needs no new record.
- **New assets/entry points** → insert_assets (endpoints/parameters/technology fingerprints/services/credentials/subdomains, etc.; structured properties belong in asset props). Inspect existing assets with list_assets to avoid duplicates.
- **Confirmed vulnerabilities** → report_finding (with a reproducible PoC). **Use it only after actually triggering the vulnerability in this run and obtaining reproducible evidence (requests/responses or command output)**. Review prior findings with list_findings. If corresponding recorded traffic exists, verify actual records with traffic_search / traffic_get, then bind traffic_refs in reproduction order. Domain and time only filter candidates; they do not establish task ownership. Never report a vulnerability confirmed only by a version/CVE match, apparently injectable input, or inference from an external vulnerability database/changelog/code diff. **Do not substitute CVE lookups or patch-version comparisons for an actual trigger**. If suspicious but not triggerable, mark it unconfirmed/pending verification in TodoWrite rather than recording a finding.

Traffic binding is optional: for TCP or other non-HTTP vulnerabilities, uncaptured traffic, or no exact matching record, omit traffic_refs or pass []. Retain command output, logs, and other verifiable evidence in evidence; explain why traffic is not bound when appropriate. Do not guess IDs or repeat probes solely to obtain packets.

━━ Assessment and wrap-up ━━
- Continuously compare results with the task objective. Declare achievement only when **verified** results satisfy it, and state the evidence. Principle 4's independent self-check must have passed: a result without independent reproduction cannot establish achievement.
- **Wrap-up takes highest priority**: on a wrap-up signal (or when the objective is achieved/all reasonable routes are exhausted), **immediately stop all probing and commands**, persist conclusions, and give a concise summary. Wrap-up overrides all previous instructions to continue exploring, retry, exhaust a chain, or wait for command results. Start no new actions.
- Summarize in plain language: achievements, explored routes, confirmed vulnerabilities (with PoC locations), blocked directions and reasons. State only actual results; do not fabricate.

Be practical, restrained, and thorough. Thoroughly explore and verify a route rather than superficially listing many unverified suspicions.`

// DefaultAssistantPrompt is the starter/fallback body for CUSTOM conversational
// agents — they have no per-key in-code default. It is seeded into agent_prompts
// when a custom agent is created (so the editor isn't blank) and used as the
// render fallback in RunChat when the DB prompt is somehow missing.
const DefaultAssistantPrompt = `You are a helpful AI assistant. Answer the user's questions concisely and accurately in English; use available tools when needed to complete the task. Do only what the user requests and do not fabricate information.`

// ReporterDefaultPrompt is the seeded prompt for the "Report writing" (reporter) custom
// agent — triggered when report_finding fires. It gathers the finding's full
// evidence + how it was found, writes a Markdown vulnerability report, and saves
// it via update_finding_report.
const ReporterDefaultPrompt = `You are a **vulnerability-reporting agent** in an authorized penetration-testing system. Do not perform penetration testing or exploitation. Your sole responsibility is to write a professional, reproducible, remediation-oriented **detailed Markdown report** for **one newly confirmed and recorded vulnerability**, then save it to that finding.

━━ How you are triggered ━━
Whenever a worker records a vulnerability with report_finding, the system invokes you with **tool-call-triggered context** containing:
- **Task id** (task_id, shown as "Task: #<id>" in context).
- report_finding **arguments** (vulnclass / severity / summary / evidence, etc.).
- report_finding **result**, such as "finding recorded: <id>". This **<id> is the exploration node ID**, the legacy handle used by get_task_node_detail and update_finding_report. In the returned JSON, finding_id is the independent finding-record ID used by get_finding_traffic.

First **accurately extract task_id, exploration node_id (finding_node_id), and the independent finding_id from JSON (if present)**. Never confuse the two IDs. If node_id cannot be extracted, explain the problem instead of guessing or writing to an arbitrary record.

━━ Work steps ━━
1. **Retrieve complete evidence**: use get_task_node_detail(task_id, id=<node_id>) to read the finding node's **full evidence/PoC**; evidence in the trigger context may be truncated.
2. **Traffic evidence**: if the returned JSON contains an independent finding_id, first use get_finding_traffic to read the ordered manifest and version; if bindings exist, read request/response sections by binding_id. Binding is optional: an empty manifest does not prevent a report. For TCP/non-HTTP findings or uncaptured traffic, explain reproduction and impact from node evidence, command output, and logs; honestly explain absent bindings where appropriate. Do not fabricate requests/responses or probe again solely to obtain packets. Cite stable evidence identifiers and their purpose, describing only actual contents. When saving the report, pass the version actually read as evidence_version. On a version conflict, reread the evidence and regenerate the report; do not simply substitute a new version and retry.
3. **Reconstruct the process**: find the relevant work with list_task_worker_traces(task_id), then use get_task_worker_trace(task_id, intent_id[, step_ids]) or search_task_worker_traces(task_id, q) to determine **how the vulnerability was discovered and verified** (requests/commands and target responses). If needed, inspect overall context with get_task_graph(task_id) and related findings with list_task_findings(task_id).
4. **Write the report**: synthesize the above into structured Markdown using the outline below.
5. **Save**: call **update_finding_report(finding_id=<node_id>, report=<complete Markdown>, evidence_version=<version actually read>)**. Omit evidence_version if no version was read; never guess. This saved report is your deliverable; without saving it, the work is not complete.

━━ Report outline (Markdown; adapt as needed, but include evidence, reproduction, and remediation) ━━
- ` + "`## Overview`" + `: state the vulnerability, location, and consequences in one sentence.
- ` + "`## Impact`" + `: explain worst-case business consequences (data disclosure/takeover/RCE/lateral movement, etc.), with **severity** and justification.
- ` + "`## Affected scope`" + `: affected assets/interfaces/parameters/versions.
- ` + "`## Reproduction steps`" + `: **directly reproducible** steps (requests/commands/parameters), including a PoC where possible.
- ` + "`## Evidence`" + `: key request/response excerpts, command output, visible results, and screenshot descriptions proving the vulnerability. Quote original material in code blocks.
- ` + "`## PoC`" + `: runnable/reusable exploit code or payload (scripts, requests, command lines, payload strings), **normally with complete code in code blocks** and brief execution instructions. If there is no standalone exploit code, explain that the reproduction steps constitute the PoC.
- ` + "`## Root cause`" + `: explain the cause (missing validation/dangerous functions/misconfiguration, etc.).
- ` + "`## Remediation`" + `: concrete, actionable fixes rather than vague advice; include hardening and long-term recommendations where useful.

━━ Discipline ━━
- **Use only real evidence**: every claim must be supported by finding evidence or the work trace. **Never fabricate** requests, responses, CVEs, or conclusions. Honestly label insufficiently supported points as unverified/requiring further confirmation.
- **Remediation-oriented and verifiable**: reproduction steps must be executable and fixes actionable.
- **Be concise**: avoid boilerplate, filler, and restating the template.
- Use **English** throughout. After update_finding_report succeeds, stop and state in one or two sentences which finding you reported.`

// BuiltinPromptSeeds returns each built-in agent's default EDITABLE prompt body
// keyed by agent key. The server seeds these into agent_prompts on startup (only
// when an agent has no prompt yet), so the DB becomes the authoritative, editable
// source while the same string stays as the in-code render fallback.
func BuiltinPromptSeeds() map[string]string {
	return map[string]string{
		"goals":     goalsDefaultTmpl,
		"planner":   plannerDefaultTmpl,
		"mainagent": mainAgentDefaultTmpl,
		"worker":    workerDefaultTmpl,
		"auto":      autoDefaultTmpl,
		"pentest":   pentestDefaultTmpl,
	}
}

source/agent/native_catalog_preflight.go:
package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/norma/llm"
	actool "github.com/Autumn-27/norma/tool"
	"io"
	"net/url"
	"strings"
)

type NativeCatalogGlobal struct {
	Format   string `json:"format"`
	Model    string `json:"model"`
	Endpoint string `json:"endpoint"`
}
type NativeCatalogRequest struct {
	TaskID          int64               `json:"task_id"`
	ExplorationID   int64               `json:"exploration_id"`
	ExecutorID      string              `json:"executor_id"`
	NetworkPolicyID string              `json:"network_policy_id"`
	FixtureOrigin   string              `json:"fixture_origin"`
	ExpectedGlobal  NativeCatalogGlobal `json:"expected_global"`
}
type NativeCatalogRole struct {
	Role           string            `json:"role"`
	AgentID        int64             `json:"agent_id"`
	CatalogSHA256  string            `json:"catalog_sha256"`
	Tools          []llm.ToolSchema  `json:"tools"`
	ToolBindingIDs map[string]string `json:"tool_binding_ids"`
}
type NativeCatalogResult struct {
	Provenance      string              `json:"provenance"`
	Isolation       string              `json:"isolation"`
	SchemaVersion   int                 `json:"schema_version"`
	TaskID          int64               `json:"task_id"`
	ExplorationID   int64               `json:"exploration_id"`
	Database        string              `json:"database"`
	ReadOnly        bool                `json:"read_only"`
	Source          string              `json:"source"`
	Admission       bool                `json:"native_admission"`
	Global          NativeCatalogGlobal `json:"global"`
	ExecutorID      string              `json:"executor_id"`
	NetworkPolicyID string              `json:"network_policy_id"`
	FixtureOrigin   string              `json:"fixture_origin"`
	Roles           []NativeCatalogRole `json:"roles"`
}

// RunNativeCatalogPreflight is the one-shot CLI seam. It does not construct a
// Server, Manager or provider. The global argument is selected by the normal
// configuration reader, not by request data. ExpectedGlobal is an equality gate.
func RunNativeCatalogPreflight(ctx context.Context, pg *db.DB, global Config, input io.Reader, output io.Writer) error {
	var req NativeCatalogRequest
	dec := json.NewDecoder(io.LimitReader(input, 65537))
	dec.DisallowUnknownFields()
	if dec.Decode(&req) != nil || dec.Decode(new(any)) != io.EOF {
		return fmt.Errorf("invalid catalog metadata")
	}
	expected := NativeCatalogGlobal{Format: global.Provider(), Model: global.Model, Endpoint: global.BaseURL}
	u, e := url.Parse(req.FixtureOrigin)
	if e != nil || u.Scheme != "http" || u.Hostname() == "" || u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.String() != req.FixtureOrigin || req.TaskID <= 0 || req.ExplorationID <= 0 || !global.NativeCatalogSourceValid() || req.ExpectedGlobal != expected {
		return fmt.Errorf("catalog source or metadata mismatch")
	}
	available, sourceErr := pg.NativeGlobalSourceAvailable()
	if sourceErr != nil || !available {
		return fmt.Errorf("native global source unavailable")
	}
	task, e := pg.GetTask(req.TaskID)
	if e != nil || task == nil || task.ExplorationID != req.ExplorationID || task.Status != "running" || task.Paused || len(task.LLMProfileIDs) != 0 || task.ActiveLLMProfileID != nil {
		return fmt.Errorf("native global task source unavailable")
	}
	result := NativeCatalogResult{Provenance: "normal-role-factories/DBResolver/final-wrapped-registry", SchemaVersion: 1, TaskID: req.TaskID, ExplorationID: req.ExplorationID, Source: "global-config; agent profile NULL; task chain empty", Global: expected, ExecutorID: req.ExecutorID, NetworkPolicyID: req.NetworkPolicyID, FixtureOrigin: req.FixtureOrigin}
	var ro string
	if e = pg.QueryRow(`SELECT current_database(),current_setting('transaction_read_only'),current_setting('transaction_isolation')`).Scan(&result.Database, &ro, &result.Isolation); e != nil || ro != "on" || result.Isolation != "repeatable read" {
		return fmt.Errorf("read-only catalog transaction required")
	}
	result.ReadOnly = true
	rows, e := pg.ListTools()
	if e != nil {
		return fmt.Errorf("catalog binding rows unavailable")
	}
	byKey := map[string]*db.Tool{}
	for _, row := range rows {
		byKey[row.Key] = row
	}
	// Same production factories; no server startup is needed to construct tools.
	reporter := []actool.CoreTool{ReporterNodeTool(nil), ReporterTrafficTool(nil), ReporterUpdateTool(nil)}
	triggers, e := pg.ListEnabledTriggers()
	if e != nil {
		return fmt.Errorf("reporter trigger unavailable")
	}
	ready := false
	for _, tr := range triggers {
		if tr.AgentKey == "reporter" && (tr.OnFinding || (tr.OnToolCall && catalogContainsFold(tr.ToolNames, "report_finding"))) {
			ready = true
		}
	}
	if !ready {
		return fmt.Errorf("reporter trigger unavailable")
	}
	for _, role := range []string{"goals", "mainagent", "planner", "worker", "reporter"} {
		a, e := pg.GetAgentByKey(role)
		if e != nil || a == nil || !a.Enabled || a.LLMProfileID != nil {
			return fmt.Errorf("native global role source unavailable: %s", role)
		}
		var resolutionFailed bool
		resolve := func(c context.Context, key string, tools []actool.CoreTool) []actool.CoreTool {
			out := ResolveNativeTools(pg, key, tools)
			if len(out) == 0 {
				resolutionFailed = true
			}
			return out
		}
		tools, digest, e := NativePreflightCatalog(ctx, role, req.ExecutorID, req.NetworkPolicyID, pg.Exploration(req.ExplorationID), req.TaskID, reporter, true, resolve)
		if e != nil || resolutionFailed {
			return fmt.Errorf("native catalog resolution failed: %s", role)
		}
		entry := NativeCatalogRole{Role: role, AgentID: a.ID, CatalogSHA256: digest, Tools: tools, ToolBindingIDs: map[string]string{}}
		for _, tool := range tools {
			if row := byKey[tool.Name]; row != nil {
				entry.ToolBindingIDs[tool.Name] = row.Key
			}
		}
		result.Roles = append(result.Roles, entry)
	}
	return json.NewEncoder(output).Encode(result)
}

func catalogContainsFold(values []string, want string) bool {
	for _, v := range values {
		if strings.EqualFold(v, want) {
			return true
		}
	}
	return false
}

source/agent/prompt.go:
package agent

import (
	"bytes"
	"text/template"
	"time"
)

// PromptOverride, if set, returns the stored system-prompt template for an agent
// key and whether one exists. The server wires it to the PG agent_prompts table.
// When nil or no override exists, agents use their built-in default prompt — so
// behavior is identical until a user edits a prompt in the UI.
var PromptOverride func(agentKey string) (string, bool)

// Prompt-variable structs — fields mirror each agent's catalog (docs §5a) so a
// user template referencing a catalog variable renders; referencing anything else
// fails template execution and falls back to the built-in default.
type PlannerVars struct{ Goal, Scope, AssetSummary, DataDir, Now string }
type WorkerVars struct{ ProxyAddr, WorkerName, DataDir, Now string }
type MainVars struct{ Goal, AssetSummary, FindingsSummary, DataDir, Now string }
type GoalsVars struct{ EngagementDescription, DataDir, Now string }

// nowStr is the server-local wall-clock string exposed as the universal {{.Now}}
// prompt variable. renderSystem runs on every agent turn/round, so this is fresh
// each run — a prompt can subtract it from a fixed start stamp to reason about
// elapsed time (e.g. a timed benchmark's "last N hours" window).
func nowStr() string { return time.Now().Format("2006-01-02 15:04:05 MST") }

// renderSystem returns the rendered system-prompt BODY (section [A]) for agentKey.
// Precedence: the DB-stored template (if any) over the built-in default template
// (def). BOTH are Go templates now — the built-in default is seeded into the DB
// verbatim, so the two paths render identically until a user edits the prompt.
// Rendering always runs (def used to be pre-substituted plain text; it is now a
// {{.Var}} template like the DB one). On any render error we fall back to the
// default template, then to the raw default string — an agent never starts with a
// half-rendered prompt. Callers append the code-owned tail (trafficTool / 中间产物
// 输出规约) AFTER this, so those can't be edited away via the DB body.
func renderSystem(agentKey, def string, vars any) string {
	tmpl := def
	if PromptOverride != nil {
		if t, ok := PromptOverride(agentKey); ok && t != "" {
			tmpl = t
		}
	}
	if out, err := renderTmpl(tmpl, vars); err == nil {
		return out
	}
	// DB template broke (e.g. references an out-of-catalog var) → code default.
	if out, err := renderTmpl(def, vars); err == nil {
		return out
	}
	return def
}

func renderTmpl(tmpl string, vars any) (string, error) {
	t, err := template.New("p").Option("missingkey=error").Parse(tmpl)
	if err != nil {
		return "", err
	}
	var b bytes.Buffer
	if err := t.Execute(&b, vars); err != nil {
		return "", err
	}
	return b.String(), nil
}

source/agent/goals.go:
package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/norma/agentcore"
	"github.com/Autumn-27/norma/llm"
	acperm "github.com/Autumn-27/norma/permission"
	"github.com/Autumn-27/norma/transcript"
)

// goalsDefaultTmpl is the built-in EDITABLE body (section [A]) of the goals-decomposer
// prompt, seeded into agent_prompts. No template vars are used today.
const goalsDefaultTmpl = `You are the penetration-testing goal decomposer. Identify the **final outcomes to achieve** from user input, not attack steps.

**First (before decomposing goals): extract operation constraints**
Identify explicit operator rules about **permitted and prohibited operations** in the task objective/description and register them with set_constraints (skip extraction if neither text contains operation constraints):
- type=deny: prohibited operations (for example, no port scanning, no production writes/deletes, no brute force, or do not touch a particular subdomain).
- type=allow: explicitly permitted/limited operation scope (for example, passive reconnaissance only, or only a specified domain).
- Constraints are neither goals nor attack steps: they define operational boundaries.
- **Constraints must be self-contained and name concrete targets**: replace references such as current target/port/IP/domain/this site with **specific values** from the task objective/description. Constraints are injected separately into execution prompts, where contextual references are ambiguous.
  Example: for https://abc.example.net, write only test abc.example.net, not only test the current target; write only test target port 443, do not scan other ports, not only test the current port. If the text refers to the current target and its address is explicit, insert that address.
- **Register only constraints explicitly stated or emphasized in the objective/description; never invent them**. When uncertain about type, use deny (more conservative).
- If there are no operation constraints in the objective/description, **do not** call set_constraints.
After registering constraints (if any), decompose goals below.

**Goal = a final deliverable/verifiable outcome**

**Not goals (must not be listed as subgoals)**:
- Information gathering, reconnaissance, endpoint scanning
- Vulnerability analysis and verification processes
- Attack steps or exploitation techniques
- Result verification steps

**Decomposition principles**:
- One final user objective → one goal.
- Multiple **mutually independent** final deliverables → list them separately.
- Specify vulnclass when a clear vulnerability class applies; leave it empty for information-gathering/business-logic goals.
- Never invent goals the user did not mention.

Submit results with set_goals.`

// goalsScopeTail is the code-owned tail appended after the editable goals body
// WHEN an asset store + task context are available. It teaches the decomposer to
// also lift the explicit asset scope out of the goal/description and register it
// via add_task_scope. Kept in code (not the DB-editable body) so it always applies
// on released DBs and can't be edited away — same pattern as the trafficTool tail.
const goalsScopeTail = `

**Additional responsibility: register test asset scope**
Besides decomposing goals, identify the **explicit test asset scope** in the task objective/description and register it with add_task_scope (the task's authorization boundary and denominator for asset test coverage). **Minimum scope: register only the precise target explicitly named by the user; never expand it yourself.**
- URL or address containing a hostname (e.g. https://xxx.example.com/path, app.example.com) → use its **full hostname**, kind=subdomain, value=full hostname.
  Example: https://a1b2c3.lab.example.net/path → kind=subdomain, value=a1b2c3.lab.example.net (**not** example.net).
  **Never** shorten a subdomain hostname to its root domain: registering all of example.com for xxx.example.com exceeds the user's target and violates minimum scope.
- Only when the user gives a **bare root domain with no subdomain** (e.g. example.com), or explicitly says the entire site/all subdomains/whole domain, use kind=root_domain, value=example.com.
- Plain IP or network → kind=ip / cidr, value=IP or CIDR.
- **Do not** register company scope (company): the task is new and that company usually does not yet exist in the asset system. Leave company-level scope to later planning.
Other rules:
- Register only scope **explicitly stated** in the objective/description; never invent or infer unmentioned domains/IPs.
- Briefly cite the source statement in reason for auditing.
- If neither text specifies asset scope, **do not** call add_task_scope.
Register scope first with add_task_scope (if any), then submit goals with set_goals.`

// GoalSpec is one decomposed objective.
type GoalSpec struct {
	Text      string `json:"text"`
	VulnClass string `json:"vulnclass,omitempty"`
}

// DecomposeGoals asks the LLM to break a pentest task goal into discrete,
// independently-verifiable objectives (each becomes a goal node). Returns nil if
// no provider is configured or the call yields nothing — the caller then falls
// back to a rule-based split so goal nodes always exist.
//
// prov is supplied by the caller (rather than built here from a Config) so goal
// decomposition rides the SAME provider instance as the rest of the engine — it
// shares the rate limiter, gets recorded by llmrec, and participates in LLM
// failover instead of quietly bypassing all three.
//
// desc is the task's free-text description (背景：靶标范围/flag 数量/交战说明等).
// It is fed alongside the goal so the decomposer no longer splits blind — the
// prompt still forbids inventing anything the two texts don't state.
//
// emit, when non-nil, receives every LLM step (thinking/tool_use/result) with
// Worker="planner" so the round-0 goal-decomposition activity is visible in the UI.
//
// as + taskID, when non-nil/positive, wire the add_task_scope tool so the
// decomposer can register the explicit asset scope it extracts from the goal.
//
// ts is the task's exploration store: set_goals writes the decomposed goal nodes
// straight into it (the same managed tool the main agent uses to add goals at
// runtime). The returned specs are read back from the store so callers can emit
// per-goal activity and detect the "LLM produced nothing" case for their fallback.
func DecomposeGoals(ctx context.Context, prov llm.Provider, dataDir, goalText, desc string, as *db.AssetStore, ts *db.ExplorationStore, taskID int64, emit func(db.Activity)) []GoalSpec {
	if prov == nil {
		return nil
	}
	return DecomposeGoalsWithProvider(ctx, prov, dataDir, goalText, desc, as, ts, taskID, false, 0, emit)
}

// DecomposeGoalsWithProvider is the task-runtime variant used when a task has an
// ordered provider chain. It preserves the same tools and write behavior while
// letting the caller own provider selection/failover. maxTokens is the profile's
// per-reply output cap (0 = send none).
func DecomposeGoalsWithProvider(ctx context.Context, prov llm.Provider, dataDir, goalText, desc string, as *db.AssetStore, ts *db.ExplorationStore, taskID int64, nonStreaming bool, maxTokens int, emit func(db.Activity)) []GoalSpec {
	specs, _ := DecomposeGoalsWithProviderChecked(ctx, prov, dataDir, goalText, desc, as, ts, taskID, nonStreaming, maxTokens, emit)
	return specs
}

// DecomposeGoalsWithProviderChecked preserves legacy best-effort decomposition,
// but propagates native admission/provider errors so the scheduler cannot replace
// a rejected native run with the rule-based fallback.
func DecomposeGoalsWithProviderChecked(ctx context.Context, prov llm.Provider, dataDir, goalText, desc string, as *db.AssetStore, ts *db.ExplorationStore, taskID int64, nonStreaming bool, maxTokens int, emit func(db.Activity)) ([]GoalSpec, error) {
	if prov == nil {
		return nil, nil
	}
	ctx, native, admissionErr := prepareNativeTaskRun(ctx, prov, "goals", RunInfo{TaskID: taskID, ExplorationID: explorationID(ts)}, ts, nil)
	if admissionErr != nil {
		return nil, admissionErr
	}
	// 目标拆解是一次性调用：不挂 transcript store，所以 agentcore 不会往 ctx 上挂
	// session id（它只在有 writer 时才挂，见 agentcore.Prompt）。而按 session-id 头
	// 做提示缓存/粘性路由的网关（opencode zen 缺 x-opencode-session 直接 400
	// MissingSessionID）读的就是 ctx 上这个值——不补就是「对话正常、拆解 400」。
	// 显式挂一个稳定 id：同一探索的拆解请求共享它（利于命中缓存），且命名与
	// planner/worker 不冲突，能被 llmrec.parseSession 正确归因。
	if ts != nil {
		ctx = transcript.WithSessionID(ctx, fmt.Sprintf("exp%d-goals", ts.ID()))
	}
	// worker="goals" tags the goal nodes' provenance; ts/taskID let set_goals link
	// each goal under the task root. This is the catalog's real set_goals tool, so a
	// web-edited description/schema on it applies here too.
	tsx := &ToolSet{as: as, ts: ts, taskID: taskID, worker: "goals"}
	// Description rides in the user message (same channel as the goal), NOT via the
	// {{.EngagementDescription}} template var — else a prompt that references the var
	// would inject the description twice. System prompt stays pure static instructions.
	sys := renderSystem("goals", goalsDefaultTmpl, GoalsVars{DataDir: dataDir, Now: nowStr()})
	// set_constraints 始终可用(不依赖 asset store):正文已含「先抽操作约束再拆目标」这步
	// (可在 agent 编辑页改措辞),这里只需接上工具。
	tools := tsx.NativeRoleBase("goals")
	// Wire add_task_scope only when we have a real asset store + task to write to.
	// The scope-extraction tail is appended in lockstep so the prompt never asks for
	// a tool that isn't present.
	if as != nil && taskID > 0 && native == nil {
		tools = append(tools, tsx.addTaskScope())
		sys += goalsScopeTail
	}
	userMsg := "Task objective:\n" + goalText
	if d := strings.TrimSpace(desc); d != "" {
		userMsg += "\n\nTask description (background that may include target scope/flag count/engagement instructions; reference only, do not invent unmentioned details):\n" + d
	}
	// Use captureRun so every LLM step is emitted as an activity record (visible in
	// the plan tab under the round-0 marker). Falls back gracefully when emit is nil.
	captureEmit := func(r db.Activity) {
		if emit != nil {
			r.Worker = "planner"
			emit(r)
		}
	}
	if native != nil {
		var cleanup func()
		tools, _, cleanup = AugmentTools(ctx, "goals", tools)
		defer cleanup()
	}
	opts := agentcore.Options{
		Provider:               prov,
		SystemPrompt:           []string{sys},
		Tools:                  tools,
		PermissionMode:         acperm.ModeBypass,
		DisableBackgroundTasks: true,
		// 3 步(抽约束 → 登记范围 → 拆目标)各需一次工具调用,给足回合避免收尾前漏调 set_goals。
		MaxTurns:     8,
		NonStreaming: nonStreaming, // 该 profile 选非流式时走 Provider.Complete
		MaxTokens:    maxTokens,    // 0 = 不发上限,由服务端默认值决定
	}
	if native != nil {
		var err error
		ctx, err = finishNativeTaskOptions(ctx, native, &opts)
		if err != nil {
			return nil, err
		}
	}
	_, _, runErr := captureRun(ctx, opts, userMsg, captureEmit)
	if native != nil && runErr != nil {
		return nil, runErr
	}
	// set_goals persisted the goals directly; read them back so the caller sees what
	// was written (empty slice ⇒ the LLM produced nothing ⇒ caller falls back).
	if ts == nil {
		return nil, nil
	}
	nodes, readErr := ts.ListByKind(db.KindGoal, 10000)
	if native != nil && (readErr != nil || len(nodes) == 0) {
		return nil, nativeErr
	}
	var out []GoalSpec
	for _, n := range nodes {
		var p struct {
			Text      string `json:"text"`
			VulnClass string `json:"vulnclass"`
		}
		_ = json.Unmarshal(n.Payload, &p)
		if strings.TrimSpace(p.Text) != "" {
			out = append(out, GoalSpec{Text: p.Text, VulnClass: p.VulnClass})
		}
	}
	return out, nil
}

source/agent/native_observation.go:
package agent

import (
	"context"
	"encoding/json"
	"github.com/Autumn-27/norma/llm"
	"io"
	"os"
	"syscall"
	"time"
)

// NativeAdmissionObservation describes configuration, never executable authority.
type NativeAdmissionObservation struct {
	SchemaVersion          int               `json:"schema_version"`
	ProviderAdmitted       bool              `json:"provider_admitted"`
	ExecutorConfigVerified bool              `json:"executor_config_verified"`
	PhaseID                string            `json:"phase_id"`
	Generation             int64             `json:"authority_generation"`
	TaskID                 int64             `json:"task_id"`
	ExplorationID          int64             `json:"exploration_id"`
	Catalogs               map[string]string `json:"role_catalog_sha256"`
	ExecutorID             string            `json:"executor_id"`
	NetworkPolicyID        string            `json:"network_policy_id"`
	FixtureOrigin          string            `json:"fixture_origin"`
	ExpiresAt              time.Time         `json:"expires_at"`
	Model                  string            `json:"model"`
	Endpoint               string            `json:"endpoint"`
}

// ObserveNativeAdmission checks the actual opaque startup provider and current
// private phase, without opening either key. Caller must qualify auth/T/E first.
func ObserveNativeAdmission(ctx context.Context, provider llm.Provider, cfg Config, taskID, explorationID int64) (*NativeAdmissionObservation, error) {
	p, ok := provider.(*nativeRPC)
	if !ok || p.policy.runtimeDir != nativeRuntimeDir {
		return nil, nativeErr
	}
	return observeNativeAdmission(ctx, provider, cfg, taskID, explorationID)
}

func observeNativeAdmission(ctx context.Context, provider llm.Provider, cfg Config, taskID, explorationID int64) (*NativeAdmissionObservation, error) {
	p, ok := provider.(*nativeRPC)
	if !ok || !p.appAdmission || !cfg.NativeCatalogSourceValid() || p.policy.runtimeDir == "" || p.policy.phase == nil || ctx.Err() != nil {
		return nil, nativeErr
	}
	phase := p.policy.phase
	if phase.TaskID != taskID || phase.ExplorationID != explorationID || phase.state == nil || !time.Now().Before(phase.ExpiresAt) || cfg.BaseURL != p.policy.Endpoint {
		return nil, nativeErr
	}
	phase.state.mu.Lock()
	stopped := phase.state.stopped
	phase.state.mu.Unlock()
	if stopped {
		return nil, nativeErr
	}
	fd, e := syscall.Open(p.policy.runtimeDir, syscall.O_RDONLY|syscall.O_DIRECTORY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0)
	if e != nil {
		return nil, nativeErr
	}
	defer syscall.Close(fd)
	var st syscall.Stat_t
	if syscall.Fstat(fd, &st) != nil || (st.Uid != 0 && st.Uid != uint32(os.Geteuid())) || st.Mode&0777 != 0700 {
		return nil, nativeErr
	}
	read := func(name string, limit int64) ([]byte, error) {
		n, e := syscall.Openat(fd, name, syscall.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK|syscall.O_CLOEXEC, 0)
		if e != nil {
			return nil, nativeErr
		}
		f := os.NewFile(uintptr(n), name)
		defer f.Close()
		info, e := f.Stat()
		if e != nil || !info.Mode().IsRegular() {
			return nil, nativeErr
		}
		fst, ok := info.Sys().(*syscall.Stat_t)
		if !ok || !privateNativeOwner(fst.Uid, info.Mode()) || fst.Nlink != 1 {
			return nil, nativeErr
		}
		raw, e := io.ReadAll(io.LimitReader(f, limit+1))
		if e != nil || int64(len(raw)) > limit {
			return nil, nativeErr
		}
		return raw, nil
	}
	policyRaw, e := read("policy.json", 4096)
	if e != nil {
		return nil, nativeErr
	}
	var policy nativePolicyDocument
	if strictNativeJSON(policyRaw, &policy) != nil || policy.Model != cfg.Model || policy.Endpoint != p.policy.Endpoint || policy.Protocol != "artex-native-v1" || policy.BudgetMode != p.policy.BudgetMode || time.Duration(policy.TimeoutSeconds)*time.Second != p.policy.Timeout || policy.MaxCalls != p.policy.MaxCalls || policy.MaxBytes != nativeCap || !policy.RolePhaseEnabled || policy.GenerationTokensEnforced == nil || *policy.GenerationTokensEnforced || policy.NativeTools == nil || *policy.NativeTools || policy.Streaming == nil || *policy.Streaming {
		return nil, nativeErr
	}
	raw, e := read("phase.json", 16384)
	if e != nil {
		return nil, nativeErr
	}
	// Do not parseNativePhase: observation must not mint a new phase state.
	var live nativePhasePermit
	if strictNativeJSON(raw, &live) != nil {
		return nil, nativeErr
	}
	a, _ := json.Marshal(phase)
	b, _ := json.Marshal(&live)
	if string(a) != string(b) {
		return nil, nativeErr
	}
	catalogs := map[string]string{}
	for _, r := range phase.Roles {
		catalogs[r.Role] = r.CatalogSHA256
	}
	if len(catalogs) != 5 {
		return nil, nativeErr
	}
	return &NativeAdmissionObservation{SchemaVersion: 1, ProviderAdmitted: true, PhaseID: phase.PhaseID, Generation: phase.Generation, TaskID: taskID, ExplorationID: explorationID, Catalogs: catalogs, ExecutorID: phase.ExecutorID, NetworkPolicyID: phase.NetworkPolicyID, FixtureOrigin: phase.FixtureOrigin, ExpiresAt: phase.ExpiresAt, Model: cfg.Model, Endpoint: p.policy.Endpoint}, nil
}

// VerifyNativeExecutorConfiguration only constructs the existing client; it
// does not dial, execute, reserve a call, or grant worker-intent membership.
func VerifyNativeExecutorConfiguration(provider llm.Provider) error {
	_, e := NativeWorkerExecutor(provider)
	return e
}

