package agent

import (
	"context"
	"fmt"
	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/artex/nativeexec"
	"github.com/Autumn-27/norma/agentcore"
	"github.com/Autumn-27/norma/harness"
	"github.com/Autumn-27/norma/llm"
	actool "github.com/Autumn-27/norma/tool"
	"github.com/Autumn-27/norma/transcript"
	"reflect"
)

// nativeTaskScope exists only after a live exploration-to-task check. It is not
// constructible from RunInfo, a chat marker, prompt text or model arguments.
type nativeTaskScope struct {
	provider       *nativeRPC
	store          *db.ExplorationStore
	run            RunInfo
	role           string
	executor       nativeexec.Executor
	validate       func(context.Context, string) error
	reportingReady bool
}
type nativeTaskScopeKey struct{}

func checkNativeTaskMembership(ts *db.ExplorationStore, ri RunInfo, role string) error {
	if ts == nil || ri.TaskID <= 0 || ri.ExplorationID != ts.ID() || ri.SessionID != "" {
		return nativeErr
	}
	taskID, err := ts.TaskID()
	if err != nil || taskID != ri.TaskID {
		return nativeErr
	}
	// Inherited contexts are not a wildcard. Native source-task inheritance needs
	// an explicit reviewed policy; reject it before any normal support assembly.
	sources, err := ts.DirectSourceStores()
	if err != nil || len(sources) != 0 {
		return nativeErr
	}
	if role == "worker" {
		if ri.IntentID <= 0 {
			return nativeErr
		}
		node, err := ts.GetNode(ri.IntentID)
		if err != nil || node == nil || node.Kind != "intent" || node.State != "running" {
			return nativeErr
		}
	} else if role == "reporter" {
		if ri.IntentID <= 0 {
			return nativeErr
		}
		n, e := ts.GetNode(ri.IntentID)
		if e != nil || n == nil || n.Kind != db.KindIntent {
			return nativeErr
		}
	} else if ri.IntentID != 0 {
		return nativeErr
	}
	return nil
}

// BindNativeTaskRole is the DB-backed host launch boundary. Dynamic worker
// templates cannot be used by BindNativeRole; only this path mints a child run.
func (p *nativeRPC) BindNativeTaskRole(ctx context.Context, role string, ri RunInfo, ts *db.ExplorationStore, tools []llm.ToolSchema) (context.Context, error) {
	if err := checkNativeTaskMembership(ts, ri, role); err != nil {
		return nil, err
	}
	phase := p.policy.phase
	if phase == nil || phase.TaskID != ri.TaskID || phase.ExplorationID != ri.ExplorationID {
		return nil, nativeErr
	}
	scope := nativeTaskScope{provider: p, store: ts, run: ri, role: role}
	if prior, ok := ctx.Value(nativeTaskScopeKey{}).(nativeTaskScope); ok && prior.provider == p && prior.run == ri && prior.role == role {
		scope.executor = prior.executor
		scope.validate = prior.validate
		scope.reportingReady = prior.reportingReady
	}
	ctx = context.WithValue(ctx, nativeTaskScopeKey{}, scope)
	if role == "reporter" {
		return p.bindNativeReporter(ctx, ri, tools)
	}
	if role != "worker" {
		return p.BindNativeRole(ctx, role, "run", ri, tools)
	}
	for _, template := range phase.Roles {
		if template.Role != "worker" || !template.DynamicIntent {
			continue
		}
		if RunInfoFrom(ctx) != ri || transcript.SessionIDFrom(ctx) != WorkerSessionID(ri.ExplorationID, ri.IntentID) {
			return nil, nativeErr
		}
		hash, err := nativeRoleCatalog(phase, template, tools)
		if err != nil || hash != template.CatalogSHA256 {
			return nil, nativeErr
		}
		child := template
		child.IntentID = ri.IntentID
		child.SessionID = WorkerSessionID(ri.ExplorationID, ri.IntentID)
		child.DynamicIntent = false
		bound := context.WithValue(ctx, nativeRoleAdmissionKey{}, nativeRoleAdmission{phase.state, child, ri})
		if !p.validateNativeRole(bound, llm.CompletionRequest{Tools: tools}) {
			return nil, nativeErr
		}
		return bound, nil
	}
	return nil, nativeErr
}

func prepareNativeTaskRun(ctx context.Context, prov llm.Provider, role string, ri RunInfo, ts *db.ExplorationStore, executor nativeexec.Executor, loaders ...func(llm.Provider) (nativeexec.Executor, error)) (context.Context, *nativeRPC, error) {
	original := prov
	ctx = WithRunInfo(ctx, ri)
	if ctx.Err() != nil {
		return nil, nil, ctx.Err()
	}
	if source, ok := prov.(interface {
		NativeTaskProvider(context.Context) (llm.Provider, error)
	}); ok {
		// Resolve a runtime source only after the live task membership check. Pin the
		// selected native provider for the whole run; never rotate to a legacy engine.
		if err := checkNativeTaskMembership(ts, ri, role); err != nil {
			return nil, nil, err
		}
		var err error
		prov, err = source.NativeTaskProvider(ctx)
		if err != nil {
			return nil, nil, err
		}
	}
	p, ok := prov.(*nativeRPC)
	if !ok {
		return ctx, nil, nil
	}
	if p.policy.phase == nil || !p.appAdmission || ri.TaskID != p.policy.phase.TaskID || ri.ExplorationID != p.policy.phase.ExplorationID {
		return nil, nil, nativeErr
	}
	if role == "worker" {
		if err := checkNativeTaskMembership(ts, ri, role); err != nil {
			return nil, nil, err
		}
		if executor == nil && len(loaders) == 1 && loaders[0] != nil {
			var err error
			executor, err = loaders[0](p)
			if err != nil {
				return nil, nil, nativeErr
			}
		}
		if executor == nil {
			return nil, nil, fmt.Errorf("%w: isolated worker executor unavailable", nativeErr)
		}
		v := reflect.ValueOf(executor)
		if (v.Kind() == reflect.Pointer || v.Kind() == reflect.Interface) && v.IsNil() {
			return nil, nil, nativeErr
		}
	}
	if err := checkNativeTaskMembership(ts, ri, role); err != nil {
		return nil, nil, err
	}
	session := fmt.Sprintf("exp%d-%s", ri.ExplorationID, role)
	if role == "worker" {
		session = WorkerSessionID(ri.ExplorationID, ri.IntentID)
	}
	if role == "mainagent" {
		session = fmt.Sprintf("exp%d-main", ri.ExplorationID)
	}
	if role == "reporter" {
		event, ok := ctx.Value(nativeFindingKey{}).(nativeFindingAuthority)
		if !ok || event.validate(ctx) != nil {
			return nil, nil, nativeErr
		}
		session = fmt.Sprintf("conv-%d", event.conversation)
	}
	ctx = WithRunInfo(transcript.WithSessionID(ctx, session), ri)
	scope := nativeTaskScope{provider: p, store: ts, run: ri, role: role, executor: executor}
	if ready, ok := original.(interface{ NativeReportingReady(context.Context) bool }); ok && nativeReporterTemplate(p) {
		scope.reportingReady = ready.NativeReportingReady(ctx)
	}
	if validator, ok := original.(interface {
		ValidateNativeTaskRun(context.Context, RunInfo, string, string) error
	}); ok {
		scope.validate = func(c context.Context, name string) error {
			if e := validator.ValidateNativeTaskRun(c, ri, role, name); e != nil {
				return e
			}
			if source, ok := original.(interface{ NativeTaskSourceMatches(llm.Provider) bool }); ok && !source.NativeTaskSourceMatches(p) {
				return nativeErr
			}
			return nil
		}
	}
	return context.WithValue(ctx, nativeTaskScopeKey{}, scope), p, nil
}

func finishNativeTaskOptions(ctx context.Context, p *nativeRPC, opts *agentcore.Options) (context.Context, error) {
	scope, ok := ctx.Value(nativeTaskScopeKey{}).(nativeTaskScope)
	if !ok || scope.provider != p {
		return nil, nativeErr
	}
	opts.Provider = p
	opts.SessionID = transcript.SessionIDFrom(ctx)
	opts.EnableWebFetch = false
	opts.EnableWebSearch = false
	opts.WebFetchProxy = ""
	opts.WebFetchCACert = ""
	opts.WebSearchProxy = ""
	opts.BraveSearchAPIKey = ""
	opts.TavilySearchAPIKey = ""
	opts.DeepSeekSearchAPIKey = ""
	opts.DeepSeekSearchBaseURL = ""
	opts.DeepSeekSearchModel = ""
	opts.BashEnv = nil
	opts.Todos = nil
	opts.AskUser = nil
	opts.Plan = nil
	opts.Memory = nil
	opts.Skills = nil
	opts.DeferredTools = nil
	opts.UnlockSet = nil
	opts.DisableBackgroundTasks = true
	opts.Compaction = nil
	opts.Compactor = nil
	opts.Settlement = nil
	opts.Deps = harness.QueryDeps{}
	opts.Hooks = nil // native effects use the sealed final-argument boundary, never host hooks
	opts.TokenBudget = 0
	opts.EscalateMaxTokens = false
	opts.NonStreaming = true
	return p.BindNativeTaskRole(ctx, scope.role, scope.run, scope.store, actool.NewRegistry(opts.Tools...).Schemas())
}

// AdmittedNativeTaskProvider preserves an already admitted opaque provider.
// Marker interfaces and RunInfo are deliberately insufficient.
func AdmittedNativeTaskProvider(p llm.Provider) (llm.Provider, bool) {
	n, ok := p.(*nativeRPC)
	if !ok || !n.appAdmission || n.policy.phase == nil {
		return nil, false
	}
	return n, true
}

// IsNativeRoleRun exposes only the mode, not the opaque phase authority.
func IsNativeRoleRun(ctx context.Context) bool { return nativeRoleContext(ctx) }

func nativeRoleContext(ctx context.Context) bool {
	if _, ok := ctx.Value(nativeTaskScopeKey{}).(nativeTaskScope); ok {
		return true
	}
	_, ok := ctx.Value(nativeRoleAdmissionKey{}).(nativeRoleAdmission)
	return ok
}

source/agent/reporter_factories.go:
package agent

import (
	"context"
	"encoding/json"
	"github.com/Autumn-27/norma/permission"
	actool "github.com/Autumn-27/norma/tool"
)

// Reporter factories own metadata for both normal server handlers and preflight.
// A nil handler is schema-only and fails closed if accidentally called.
func reporterBaseTool(readOnly bool, name, desc string, schema map[string]any, run func(context.Context, json.RawMessage) (actool.Result, error)) actool.CoreTool {
	spec := actool.Spec{Name: name, Description: desc, Schema: schema,
		Permissions: func(context.Context, json.RawMessage, permission.Context) permission.Decision {
			return permission.Allowed()
		},
		Run: func(ctx context.Context, in json.RawMessage, _ *actool.ToolContext) (actool.Result, error) {
			if run == nil {
				return actool.Result{}, nativeErr
			}
			if e := ValidateNativeDomainInput(ctx, name, schema, in); e != nil {
				return actool.Result{}, e
			}
			return run(ctx, in)
		}}
	if readOnly {
		spec.ReadOnly = func(json.RawMessage) bool { return true }
		spec.Concurrent = func(json.RawMessage) bool { return true }
	}
	return actool.Build(spec)
}
func reporterStrParam(desc string) map[string]any {
	return map[string]any{"type": "string", "description": desc}
}
func reporterObjSchema(properties map[string]any, required ...string) map[string]any {
	out := map[string]any{"type": "object", "properties": properties}
	if len(required) > 0 {
		req := make([]any, len(required))
		for i, r := range required {
			req[i] = r
		}
		out["required"] = req
	}
	return out
}
func ReporterNodeTool(run func(context.Context, json.RawMessage) (actool.Result, error)) actool.CoreTool {
	return reporterBaseTool(true, "get_task_node_detail",
		"Read complete contents of an exploration node in a specified task (finding/fact/intent/goal: summary plus detail/evidence/PoC). id is the exploration node ID (returned by report_finding or listed as id in list_task_findings). Retrieve the complete evidence before writing a vulnerability report.",
		reporterObjSchema(map[string]any{
			"task_id": reporterStrParam("Task id"),
			"id":      map[string]any{"type": "integer", "description": "Exploration node id (not asset id)"},
		}, "task_id", "id"), run)
}
func ReporterUpdateTool(run func(context.Context, json.RawMessage) (actool.Result, error)) actool.CoreTool {
	return reporterBaseTool(false, "update_finding_report",
		"Write/update a detailed report for a recorded vulnerability (complete Markdown, replacing the old contents). Pass the exploration node id returned by report_finding (the number in \"finding recorded: <id>\") as finding_id. Include overview, impact, reproduction steps, evidence/PoC, and remediation.",
		reporterObjSchema(map[string]any{
			"finding_id":       map[string]any{"type": "integer", "description": "Target finding node id (id returned by report_finding)"},
			"report":           reporterStrParam("Complete detailed report in Markdown"),
			"evidence_version": map[string]any{"type": "integer", "description": "Evidence version returned by get_finding_traffic; prevents saving a report over newer evidence changes"},
		}, "finding_id", "report"), run)
}
func ReporterTrafficTool(run func(context.Context, json.RawMessage) (actool.Result, error)) actool.CoreTool {
	return reporterBaseTool(true, "get_finding_traffic", "Read real traffic evidence bound to a finding, independently of capture settings. Use the independent finding-record ID from report_finding JSON as finding_id (not the exploration node ID on the first line). Omit binding_id initially to retrieve the manifest and version. An empty manifest is normal: for TCP/non-HTTP or uncaptured traffic, write the report from text/command evidence; binding is not mandatory. If bindings exist, read body segments using binding_id, side(request/response), and offset. Pass the version actually read as evidence_version to update_finding_report, whose finding_id still uses the exploration node ID.",
		reporterObjSchema(map[string]any{"finding_id": reporterStrParam("Independent finding-record ID"), "binding_id": reporterStrParam("Binding ID from the manifest; omit to return the manifest"), "side": reporterStrParam("request or response; default response"), "offset": map[string]any{"type": "integer"}, "length": map[string]any{"type": "integer"}}, "finding_id"), run)
}

source/agent/tools_digest.go:
package agent

// cold-digest §6: graph_overview folding + the restore tools.
//
//	coldDigestsRecent — builds the folded cold region for graph_overview:
//	  cold_digests (flat {id, body, member_count}), newest-member first, capped.
//	expand_digest(id)  — level-1 restore: a digest's member compact list.

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"

	"github.com/Autumn-27/artex/db"
	actool "github.com/Autumn-27/norma/tool"
)

// digestMemberEntry builds the compact per-member view expand_digest returns —
// same shape as recent_facts / recent_done_intents (§6.1 middle level). store is
// the digest's OWNING store (the current task, or a read-only source task §2).
func (t *ToolSet) digestMemberEntry(store *db.ExplorationStore, id int64) map[string]any {
	n, _ := store.GetNode(id)
	if n == nil {
		return map[string]any{"id": id, "missing": true}
	}
	m := compactNode(n)
	m["state"] = n.State
	var p map[string]any
	if json.Unmarshal(n.Payload, &p) == nil {
		if c, ok := p["confidence"].(string); ok && c != "" {
			m["confidence"] = c
		}
	}
	return m
}

// coldDigestsRecent returns a store's active digests as flat bodies for
// graph_overview, ordered by the recency of their freshest member (max member id ≈
// latest cooled node — a digest near the live frontier is likelier relevant), and
// capped at `cap`. Overflow digest ids are returned separately (moreIDs) so they
// stay reachable via expand_digest even when not shown inline — cold_digests is the
// only exit for folded cold nodes. Shared by the current task overview and the
// read-only related-task overview (§2 cross-task reuse).
func coldDigestsRecent(store *db.ExplorationStore, cap int) (shown []map[string]any, moreIDs []int64) {
	ads, err := store.ActiveDigests()
	if err != nil || len(ads) == 0 {
		return nil, nil
	}
	type dg struct {
		id        int64
		entry     map[string]any
		freshness int64 // max member id (ids are monotonic ≈ creation time)
	}
	items := make([]dg, 0, len(ads))
	for _, d := range ads {
		var p struct {
			Body string `json:"body"`
		}
		_ = json.Unmarshal(d.Payload, &p)
		ms, _ := store.DigestMembers(d.ID) // sorted asc → last = freshest
		var fresh int64
		if len(ms) > 0 {
			fresh = ms[len(ms)-1]
		}
		items = append(items, dg{
			id:        d.ID,
			entry:     map[string]any{"id": d.ID, "body": p.Body, "member_count": len(ms)},
			freshness: fresh,
		})
	}
	sort.Slice(items, func(i, j int) bool { return items[i].freshness > items[j].freshness })
	for i, it := range items {
		if i < cap {
			shown = append(shown, it.entry)
		} else {
			moreIDs = append(moreIDs, it.id)
		}
	}
	return shown, moreIDs
}

// hiddenMembersFor returns a predicate telling whether a member is hidden (folded
// into an active digest AND still cold) in the given store — so a source task's
// overview folds exactly the way that task folds itself (§2 cross-task: "当前任务
// 什么展示逻辑，关联任务就什么逻辑"). A revived (now hot) covered member is NOT
// hidden (§6 render-time revival check). Returns a never-hidden predicate when the
// store has no digests.
func hiddenMembersFor(store *db.ExplorationStore) func(int64) bool {
	covered, err := store.CoveredMembers()
	if err != nil || len(covered) == 0 {
		return func(int64) bool { return false }
	}
	var hot map[int64]bool
	if cg, _, err := loadColdGraph(store); err == nil {
		hot = cg.hotSet()
	}
	return func(id int64) bool { _, c := covered[id]; return c && !hot[id] }
}

// resolveDigest finds a digest node by id in the current task, else in a direct
// source task (read-only, §2). Returns the node, its owning store, and the source
// task id (0 = current task).
func (t *ToolSet) resolveDigest(id int64) (*db.Node, *db.ExplorationStore, int64) {
	if n, _ := t.ts.GetNode(id); n != nil && n.Kind == db.KindDigest {
		return n, t.ts, 0
	}
	srcs, _ := t.ts.DirectSourceStores()
	for _, s := range srcs {
		if n, _ := s.Store.GetNode(id); n != nil && n.Kind == db.KindDigest {
			return n, s.Store, s.Task.TaskID
		}
	}
	return nil, nil, 0
}

// expandDigest returns a digest's covered members as a compact list (§6.1). It is
// a distinct tool from node_detail because it returns a LIST of members, not one
// node's full detail.
func (t *ToolSet) expandDigest() actool.CoreTool {
	return t.writeExpTool("expand_digest",
		"展开一个 cold digest：返回它折叠的成员紧凑列表（id/summary/state/confidence），与概览 recent_facts/recent_done_intents 同形状。要某条完整细节/证据用 node_detail(member_id)。",
		map[string]any{
			"type": "object",
			"properties": map[string]any{
				"id": map[string]any{"type": "integer", "description": "digest 节点 id（来自概览 cold_digests）"},
			},
			"required": []any{"id"},
		},
		func(ctx context.Context, raw json.RawMessage) (actool.Result, error) {
			var in struct {
				ID int64 `json:"id"`
			}
			_ = json.Unmarshal(raw, &in)
			n, store, srcTaskID := t.resolveDigest(in.ID)
			if n == nil {
				return jsonResult(map[string]any{"error": fmt.Sprintf("#%d 不是 digest 节点（本任务或直接关联任务里都没找到）", in.ID)})
			}
			var p struct {
				Body string `json:"body"`
			}
			_ = json.Unmarshal(n.Payload, &p)
			members, _ := store.DigestMembers(in.ID)
			list := make([]map[string]any, 0, len(members))
			for _, m := range members {
				entry := t.digestMemberEntry(store, m)
				if srcTaskID > 0 { // 关联任务的成员：只读，带继承标记（§2）
					entry["inherited"] = true
					entry["source_task_id"] = srcTaskID
				}
				list = append(list, entry)
			}
			out := map[string]any{
				"id":      in.ID,
				"state":   n.State, // active / superseded
				"body":    p.Body,
				"members": list,
			}
			if srcTaskID > 0 {
				out["inherited"] = true
				out["source_task_id"] = srcTaskID
			}
			return jsonResult(out)
		})
}

source/agent/provider.go:
// Package agent wires real LLM-driven planner and work agents (on top of the
// agent-core SDK) to the dual SQLite graph. See docs/ARTEX-架构设计.md
// §4.3 (planner) and §4.4 (work agent).
//
// Provider configuration is read from the environment so the system runs with
// any Anthropic- or OpenAI-format endpoint. If no key is configured, FromEnv
// returns ok=false and the exploration engine stays idle (an LLM is required).
package agent

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/Autumn-27/artex/llmrec"
	"github.com/Autumn-27/norma/agentcore"
	"github.com/Autumn-27/norma/compaction"
	"github.com/Autumn-27/norma/llm"
	acperm "github.com/Autumn-27/norma/permission"
	"github.com/Autumn-27/norma/transcript"
)

// Config describes the LLM backend resolved from the environment.
type Config struct {
	// Native is administrator-supplied only; no UI/DB/env admission path exists.
	Native  *NativeRPCPolicy `json:"-"`
	Format  llm.Format
	BaseURL string
	APIKey  string
	Model   string
	// Proxy routes all LLM requests through the given proxy URL (http/https/socks5,
	// optionally with user:pass@ credentials). Empty means direct — it does NOT
	// fall back to the standard *_PROXY environment variables.
	Proxy string
	// RatePerSecond / RatePerMinute cap the shared request rate across ALL agents
	// using the provider (0 = that window unlimited).
	RatePerSecond float64
	RatePerMinute float64
	// ContextWindowK is the model's context window in K tokens (user-configured),
	// used to size compaction thresholds. 0 = default; see CompactionWindow.
	ContextWindowK int
	// ThinkingType 独立控制思考「开关」字段(thinking.type):
	//   "" = 不发送(默认,兼容不支持该字段的模型); "disabled" = 显式关闭;
	//   "enabled" = 开启. 与 ReasoningEffort 完全解耦——有些接口没有 thinking 字段、
	//   只靠强度参数就能激活思考,故两者可各自单独设置.
	ThinkingType string
	// ReasoningEffort 独立控制思考「强度」字段:
	//   "" = 不发送(默认); "low"/"medium"/"high"/"xhigh"/"max" = 对应强度.
	//   OpenAI 映射为顶层 reasoning_effort;Anthropic 映射为 output_config.effort.
	ReasoningEffort string
	// Stream 控制该 profile 是否使用流式(SSE)接口。true(默认)= 流式;false = 真·
	// 非流式(发 stream:false,一次性拿完整 JSON,走 Provider.Complete)。非流式可绕开
	// 某些网关糟糕的 SSE 实现(空帧、思考字段丢帧),代价是失去运行中的实时进度/实时
	// token 计数。映射为 agentcore.Options.NonStreaming = !Stream。
	Stream bool
	// MaxTokens 是单次回复的输出上限(token)。0 = 不发送该字段,由服务端默认值决定
	// (历史行为)。与 ContextWindowK 不同:后者是模型总容量,只在本地用来算压缩阈值,
	// 不出现在请求里;本值随每次请求发出。映射为 agentcore.Options.MaxTokens。
	MaxTokens int
	// MaxTokensField 选择 MaxTokens 用哪个请求字段名,仅对 format=openai 生效:
	//   "" = max_tokens(默认); "max_completion_tokens" = 新字段。
	// OpenAI 推理模型(o 系列/GPT-5)只认后者,收到 max_tokens 会直接报
	// unsupported_parameter;而多数兼容网关只认前者,故不做自动推断,交由用户按端点选。
	MaxTokensField string
	// SessionHeaderKey,非空时,让每次 LLM 请求带上一个自定义 HTTP 头,头名为该值、
	// 头值为【当前会话的 session id】(chat 会话=conv-<id>,worker=exp<x>-worker-i<intent>
	// 等,见 WorkerSessionID)。用于某些按 session-id 头做提示缓存/粘性路由的网关。
	// 空 = 不发送。值由 transcript.WithSessionID 挂在请求 context 上,由 RoundTripper
	// 读取填入,因此同一共享 provider 也能按会话发出不同的头值。
	SessionHeaderKey string
	// Retry 是该配置解析后的重试参数(profile 覆盖 → 全局策略 → 内置默认,由
	// server 侧解析)。三层的含义见 RetryConfig;零值 = 完全沿用内置默认。
	Retry RetryConfig
}

// RetryConfig 是随一个 LLM 配置走的重试参数。每层的「次数」统一语义:
// 0 = 用内置默认次数;负数 = 关闭该层重试;>0 = 用该值。每层的「间隔」:
// 0 = 用该层原本的指数退避;>0 = 改用这个固定间隔。
type RetryConfig struct {
	// ConnectAttempts/ConnectInterval:SDK 建连重试(连接重置/超时/429/5xx,流开始前),
	// 直接映射为 llm.Config.MaxRetries / RetryInterval。默认 3 次、0.5s 起指数(封顶 8s)。
	ConnectAttempts int
	ConnectInterval time.Duration
	// EmptyAttempts/EmptyInterval:SDK 空响应重试(完成但无 content block,仅 openai
	// 格式),映射为 llm.Config.EmptyResponseRetries / EmptyResponseInterval。
	// 默认 2 次、同一条指数梯度。
	EmptyAttempts int
	EmptyInterval time.Duration
	// StreamAttempts/StreamInterval:同 provider 安全窗口重试——本项目在 SDK 之上补的
	// 一层,只在「还没向调用方交付任何输出」时重放断流/过载/流内 429。SDK 看不到它,
	// 由 server/task_llm.go 消费。默认 2 次、0.5s 起指数(封顶 4s)。
	StreamAttempts int
	StreamInterval time.Duration
}

// compaction window resolution bounds (in K tokens). Below the floor the
// threshold math (window − summary reserve − buffer) would go non-positive and
// compaction would fire every turn; above the cap it would never fire.
const (
	defaultWindowK = 200  // unset → assume a 200K window (Claude default)
	minWindowK     = 32   // floor so effectiveWindow stays comfortably positive
	maxWindowK     = 1000 // cap at 1M tokens (user request)
)

// CompactionWindow returns the model context window in TOKENS for compaction
// thresholds, resolved from the user-configured size (ContextWindowK). 0/unset →
// a 200K default; otherwise clamped to [32K, 1M] so compaction stays effective.
func (c Config) CompactionWindow() int {
	k := c.ContextWindowK
	if k <= 0 {
		k = defaultWindowK
	}
	if k < minWindowK {
		k = minWindowK
	}
	if k > maxWindowK {
		k = maxWindowK
	}
	return k * 1000
}

// compactionConfig builds the agent-core compaction config for a context window
// in tokens. agentcore.NewSession wires the summarizer (same provider) when this
// is set on Options.Compaction.
func compactionConfig(windowTokens int) *compaction.Config {
	if windowTokens <= 0 {
		windowTokens = defaultWindowK * 1000
	}
	return &compaction.Config{ContextWindow: windowTokens}
}

// FromEnv resolves the LLM provider config:
//
//	ARTEX_LLM_PROVIDER = anthropic|openai (default: inferred from keys)
//	ARTEX_LLM_MODEL    = model id        (default: per provider)
//	ARTEX_LLM_BASE_URL = endpoint        (optional)
//	ARTEX_LLM_PROXY    = proxy URL        (optional; http/https/socks5)
//	ANTHROPIC_API_KEY / OPENAI_API_KEY         = credentials
func FromEnv() (Config, bool) {
	prov := os.Getenv("ARTEX_LLM_PROVIDER")
	if prov == "codex-native" {
		model := os.Getenv("ARTEX_LLM_MODEL")
		if model == "" {
			model = "gpt-6.1-sol"
		}
		cap := 0
		if s := os.Getenv("ARTEX_LLM_MAX_TOKENS"); s != "" {
			var e error
			cap, e = strconv.Atoi(s)
			if e != nil {
				cap = 1
			}
		}
		stream := os.Getenv("ARTEX_LLM_STREAM")
		return Config{Format: llm.Format("codex-native"), Model: model, BaseURL: os.Getenv("ARTEX_LLM_BASE_URL"), Proxy: os.Getenv("ARTEX_LLM_PROXY"), Stream: stream != "" && !isFalsy(stream), MaxTokens: cap}, true
	}
	anthKey := os.Getenv("ANTHROPIC_API_KEY")
	oaiKey := os.Getenv("OPENAI_API_KEY")

	if prov == "" {
		switch {
		case anthKey != "":
			prov = "anthropic"
		case oaiKey != "":
			prov = "openai"
		default:
			return Config{}, false
		}
	}

	c := Config{
		BaseURL: os.Getenv("ARTEX_LLM_BASE_URL"),
		Model:   os.Getenv("ARTEX_LLM_MODEL"),
		Proxy:   strings.TrimSpace(os.Getenv("ARTEX_LLM_PROXY")),
		// 默认流式;ARTEX_LLM_STREAM=false/0/off 显式关闭走非流式。
		Stream: !isFalsy(os.Getenv("ARTEX_LLM_STREAM")),
	}
	switch prov {
	case "openai":
		c.Format = llm.FormatOpenAI
		c.APIKey = oaiKey
		if c.Model == "" {
			c.Model = "gpt-4o"
		}
	case "openai-responses":
		c.Format = llm.FormatOpenAIResponses
		c.APIKey = oaiKey
		if c.Model == "" {
			c.Model = "gpt-5"
		}
	default:
		c.Format = llm.FormatAnthropic
		c.APIKey = anthKey
		if c.Model == "" {
			c.Model = "claude-opus-4-8"
		}
	}
	if c.APIKey == "" {
		return Config{}, false
	}
	return c, true
}

// ConfigFrom builds a Config from UI-provided strings (provider defaults to
// anthropic; model defaults per provider). Inputs are trimmed and the base URL
// is normalized to the API base the provider expects (the provider appends the
// endpoint path itself), so a full endpoint URL is tolerated.
func ConfigFrom(provider, model, baseURL, apiKey, proxy string) Config {
	c := Config{
		Model:   strings.TrimSpace(model),
		BaseURL: strings.TrimRight(strings.TrimSpace(baseURL), "/"),
		APIKey:  strings.TrimSpace(apiKey),
		Proxy:   strings.TrimSpace(proxy),
		Stream:  true, // 默认流式;调用方按 profile 覆盖
	}
	switch strings.TrimSpace(provider) {
	case "codex-native":
		c.Format = llm.Format("codex-native")
		c.Stream = false
	case "openai":
		c.Format = llm.FormatOpenAI
		// provider appends "/chat/completions"; tolerate a full endpoint URL.
		c.BaseURL = strings.TrimRight(strings.TrimSuffix(c.BaseURL, "/chat/completions"), "/")
		if c.Model == "" {
			c.Model = "gpt-4o"
		}
	case "openai-responses":
		c.Format = llm.FormatOpenAIResponses
		// provider appends "/responses"; tolerate a full endpoint URL.
		c.BaseURL = strings.TrimRight(strings.TrimSuffix(c.BaseURL, "/responses"), "/")
		if c.Model == "" {
			c.Model = "gpt-5"
		}
	default:
		c.Format = llm.FormatAnthropic
		// provider appends "/v1/messages".
		c.BaseURL = strings.TrimRight(strings.TrimSuffix(c.BaseURL, "/v1/messages"), "/")
		if c.Model == "" {
			c.Model = "claude-opus-4-8"
		}
	}
	return c
}

// isFalsy reports whether an env-var string explicitly requests "off". Empty or
// unrecognized → false (so an unset var keeps the streaming default).
func isFalsy(s string) bool {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "0", "false", "off", "no":
		return true
	}
	return false
}

// Provider returns the short provider name ("anthropic"/"openai").
func (c Config) Provider() string {
	switch c.Format {
	case llm.Format("codex-native"):
		return "codex-native"
	case llm.FormatOpenAI:
		return "openai"
	case llm.FormatOpenAIResponses:
		return "openai-responses"
	}
	return "anthropic"
}

// NewProvider builds an llm.Provider from the config. When a rate is set, the
// limiter lives on the single provider instance — so planner + all workers +
// main agent (which share this provider) are bounded by one shared rate limit.
func (c Config) NewProvider() (llm.Provider, error) {
	if c.Format == llm.Format("codex-native") {
		return c.admittedNativeProvider()
	}
	client, err := quotaAwareHTTPClient(c.Proxy, c.SessionHeaderKey)
	if err != nil {
		return nil, err
	}
	lc := llm.Config{
		Format:     c.Format,
		BaseURL:    c.BaseURL,
		APIKey:     c.APIKey,
		Model:      c.Model,
		HTTPClient: client,
	}
	// 思考开关与强度两个字段各自透传(空 = 该字段不发送)。二者解耦:
	// 可只发 thinking.type、只发 effort、都发、或都不发。
	lc.ThinkingType = c.ThinkingType
	lc.ReasoningEffort = c.ReasoningEffort
	// 输出上限的字段名选择(空 = 用 max_tokens)。上限的「值」不在这里:它每轮随
	// agentcore.Options.MaxTokens 走,provider 只决定把它塞进哪个键。
	lc.MaxTokensField = c.MaxTokensField
	// 重试参数与 SDK 同语义(次数 0=默认/负=关闭,间隔 0=指数退避/>0=固定),原样透传。
	lc.MaxRetries = c.Retry.ConnectAttempts
	lc.RetryInterval = c.Retry.ConnectInterval
	lc.EmptyResponseRetries = c.Retry.EmptyAttempts
	lc.EmptyResponseInterval = c.Retry.EmptyInterval
	if c.RatePerSecond > 0 || c.RatePerMinute > 0 {
		lc.RateLimit = &llm.RateLimit{PerSecond: c.RatePerSecond, PerMinute: c.RatePerMinute}
	}
	return llm.NewProvider(lc)
}

// IsQuotaExhaustedMessage deliberately recognizes only explicit balance,
// billing, credit, or quota-exhaustion signals. Generic 429/rate-limit text,
// authentication failures, network errors, and server failures are excluded.
var nonFailoverHTTPStatus = regexp.MustCompile(`(?:status(?:\s+code)?|http(?:\s+status)?)\s*[=:]?\s*(?:401|403|5\d\d)\b`)
var transientQuotaLimit = regexp.MustCompile(`(?i)(?:\b(?:rpm|tpm|rpd|qps)\b|quota[_\s-]*metric|rate[_\s-]*limit|too many requests|(?:requests?|tokens?)\s+(?:per|/)\s*(?:second|minute)|(?:per|/)\s*(?:second|minute)\s+(?:requests?|tokens?)|generate[_\s-]*requests[_\s-]*per[_\s-]*(?:minute|second)|tokens?[_\s-]*per[_\s-]*(?:minute|second))`)

func IsQuotaExhaustedMessage(message string) bool {
	message = strings.ToLower(message)
	// Authentication/authorization and provider-side 5xx failures never rotate,
	// even when a gateway happens to echo a quota-looking phrase in the body.
	if nonFailoverHTTPStatus.MatchString(message) {
		return false
	}
	// Provider APIs frequently describe an ordinary rate limit as "quota
	// exceeded", especially Google-style responses containing a quota metric.
	// These limits recover with time and must stay on the current provider.
	if transientQuotaLimit.MatchString(message) {
		return false
	}
	markers := []string{
		"insufficient_quota", "quota_exceeded", "quota exceeded", "quota exhausted",
		"exceeded your current quota", "billing_hard_limit_reached",
		"billing hard limit", "billing_not_active", "credit balance", "insufficient credit",
		"insufficient balance", "balance is too low", "payment required", "status 402",
		"余额不足", "额度不足", "额度已用尽", "欠费",
	}
	for _, marker := range markers {
		if strings.Contains(message, marker) {
			return true
		}
	}
	// gRPC RESOURCE_EXHAUSTED is overloaded for both account quota and ordinary
	// request-rate limiting. Preserve it as an explicit exhaustion signal only
	// when the same error does not identify a transient rate limit.
	return strings.Contains(message, "resource_exhausted") &&
		!strings.Contains(message, "rate limit") &&
		!strings.Contains(message, "too many requests")
}

// quotaAwareTransport preserves Norma's normal retry behavior except for a 429
// whose body explicitly says the account quota/balance is exhausted. Norma's
// retry loop treats every 429 as transient; normalizing only that response to
// 402 lets a task router fail over immediately while retaining the original
// response body for provider-specific classification and audit logs.
type quotaAwareTransport struct {
	base http.RoundTripper
	// sessionHeaderKey, when non-empty, is the HTTP header name each request
	// carries; its value is the session id read from the request context. Empty
	// disables it. See Config.SessionHeaderKey.
	sessionHeaderKey string
}

func (t quotaAwareTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	// Custom session-id header: name is user-configured, value is THIS run's
	// session id (norma stashes it on the context via transcript.WithSessionID).
	// Stable across a session's turns and distinct across sessions — exactly what
	// a session-keyed prompt cache wants. Skipped when no session id is present.
	if t.sessionHeaderKey != "" {
		if sid := transcript.SessionIDFrom(req.Context()); sid != "" {
			req.Header.Set(t.sessionHeaderKey, sid)
		}
	}
	// When LLM recording is on, the Recorder puts a Capture on the context so the
	// raw wire bodies can be persisted. This is the only layer that still sees
	// them: norma builds the request body internally and decodes the SSE response
	// before either reaches the recorder.
	capt := llmrec.CaptureFrom(req.Context())
	capt.SetRequest(requestBodySnapshot(req))

	resp, err := t.base.RoundTrip(req)
	if err != nil || resp == nil {
		return resp, err
	}
	// Tee rather than read: a 200 is an SSE stream that must keep streaming. The
	// 429 branch below reads through this wrapper, so its body lands in the
	// capture before being replaced.
	resp.Body = capt.TeeResponse(resp.StatusCode, resp.Body)

	if resp.StatusCode != http.StatusTooManyRequests {
		return resp, nil
	}
	body, readErr := io.ReadAll(resp.Body)
	_ = resp.Body.Close()
	resp.Body = io.NopCloser(bytes.NewReader(body))
	resp.ContentLength = int64(len(body))
	if readErr != nil {
		return resp, nil
	}
	if IsQuotaExhaustedMessage(string(body)) {
		resp.StatusCode = http.StatusPaymentRequired
		resp.Status = "402 Payment Required"
	}
	return resp, nil
}

// requestBodySnapshot copies an outgoing request body without consuming it.
// norma builds every model request from a *bytes.Reader, so net/http populates
// GetBody and the copy has no effect on what gets sent.
func requestBodySnapshot(req *http.Request) string {
	if req.GetBody == nil {
		return ""
	}
	rc, err := req.GetBody()
	if err != nil {
		return ""
	}
	defer rc.Close()
	b, err := io.ReadAll(rc)
	if err != nil {
		return ""
	}
	return string(b)
}

func quotaAwareHTTPClient(proxy, sessionHeaderKey string) (*http.Client, error) {
	transport := http.DefaultTransport.(*http.Transport).Clone()
	proxy = strings.TrimSpace(proxy)
	if proxy == "" {
		transport.Proxy = nil // 留空=直连,不回退 HTTP_PROXY/HTTPS_PROXY 环境变量
	} else {
		proxyURL, err := url.Parse(proxy)
		if err != nil {
			return nil, fmt.Errorf("llm: invalid proxy %q: %w", proxy, err)
		}
		switch proxyURL.Scheme {
		case "http", "https", "socks5":
		case "":
			return nil, fmt.Errorf("llm: proxy %q missing scheme (use http://, https:// or socks5://)", proxy)
		default:
			return nil, fmt.Errorf("llm: unsupported proxy scheme %q (use http, https or socks5)", proxyURL.Scheme)
		}
		transport.Proxy = http.ProxyURL(proxyURL)
	}
	return &http.Client{Transport: quotaAwareTransport{base: transport, sessionHeaderKey: strings.TrimSpace(sessionHeaderKey)}}, nil
}

// logTestConnection prints the raw HTTP status code(s) and response body of a
// connection test to the server log, so "点击测试" leaves a diagnosable trail of
// exactly what the gateway returned — 401 bodies, quota text, empty frames — not
// just the collapsed ok/err the UI shows. Bodies are clipped to keep a chatty
// SSE stream from flooding the log.
func logTestConnection(c Config, capt *llmrec.Capture) {
	attempts := capt.Attempts()
	if len(attempts) == 0 {
		log.Printf("[llm-test] %s / %s @ %s — 未发出任何 HTTP 请求(配置解析或建连即失败)",
			c.Provider(), c.Model, c.BaseURL)
		return
	}
	for i, a := range attempts {
		log.Printf("[llm-test] %s / %s @ %s — 尝试 %d/%d HTTP %d\n响应体: %s",
			c.Provider(), c.Model, c.BaseURL, i+1, len(attempts), a.Status, clipBody(a.Body))
	}
}

// clipBody trims a wire body for logging. 4K is plenty to show an error JSON or
// the head of an SSE stream while bounding a runaway response.
func clipBody(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return "(空)"
	}
	const max = 4096
	if len(s) > max {
		return s[:max] + fmt.Sprintf("…(截断,共 %d 字节)", len(s))
	}
	return s
}

// TestConnection makes a minimal real completion to verify the provider/model/
// endpoint/key actually work. Returns the round-trip latency and the model's
// reply text.
func TestConnection(ctx context.Context, c Config) (time.Duration, string, error) {
	prov, err := c.NewProvider()
	if err != nil {
		return 0, "", err
	}
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	// 抓取原始 wire 报文:连接测试最需要看到的就是网关到底回了什么(状态码+响应体),
	// 而 norma 把响应解码成 StreamEvent 后这些就没了。quotaAwareTransport 会在
	// context 里找到这个 Capture 并填入每次 HTTP 尝试的状态码与 body。
	ctx, capt := llmrec.NewCapture(ctx)
	defer logTestConnection(c, capt)
	// 连接测试是一条单发路径,不经过 agentcore 的会话循环,因此没人往 context 上挂
	// session id。对配了 SessionHeaderKey 的端点(如 opencode zen 强制要求
	// x-opencode-session 头,缺了直接 400 MissingSessionID),这会导致"对话正常、
	// 点击测试却 400"的落差。这里补挂一个一次性随机 session id,让测试与真实对话走同
	// 一套发头逻辑;未配 SessionHeaderKey 的端点不读它,无副作用。
	ctx = transcript.WithSessionID(ctx, "conntest-"+transcript.NewSessionID())
	start := time.Now()
	// MaxTokens 要给足：推理模型(如 deepseek-v4-pro)在给出答案前会先产出一大段
	// 思考(实测对一句 "ping" 也能烧 ~2900 token)。若只给 32,模型会一直卡在"思考阶段"
	// 就撞到输出上限(finish=length)、被截断,连接测试虽仍算通(err=nil)但显示成
	// "已中断/length/resume" 一团糟。给足预算让它把 OK 干净吐完(finish=stop)。
	// EscalateMaxTokens 保持 false:不因截断而抬额重试,避免 resume 循环空烧。
	reply, err := agentcore.Run(ctx, agentcore.Options{
		Provider:       prov,
		SystemPrompt:   []string{"你是连接测试。直接输出两个字符 OK 即可，不要思考、不要解释、不要别的。"},
		PermissionMode: acperm.ModeBypass,
		MaxTurns:       1,
		MaxTokens:      8192,
		NonStreaming:   !c.Stream, // 用该 profile 的真实收发模式做连接测试
	}, "ping")
	lat := time.Since(start)
	if err != nil {
		return lat, "", err
	}
	// err==nil 还不够：请求通了但模型一个字都不吐的情况真实存在(思考把预算烧光、
	// 正文被安全策略吞掉、兼容层把 content 丢了)。这种配置在会话里就是"不回话",
	// 测试却报成功——正是本项要消除的落差。没有可见正文一律判失败。
	reply = strings.TrimSpace(reply)
	if reply == "" {
		return lat, "", fmt.Errorf("模型无回复内容（请求已通，但未返回任何文本）")
	}
	return lat, reply, nil
}

