package agent

import (
	"strings"
	"testing"
	"time"
)

// TestChatNowVarRenders verifies the universal {{.Now}} runtime variable: a custom
// (chat) agent prompt referencing it renders the live server time each turn, rather
// than failing template execution and falling back to DefaultAssistantPrompt.
func TestChatNowVarRenders(t *testing.T) {
	prev := PromptOverride
	defer func() { PromptOverride = prev }()

	PromptOverride = func(key string) (string, bool) {
		if key == "tec_benchmark" {
			return "当前时间：{{.Now}}", true
		}
		return "", false
	}

	out := chatSystem("tec_benchmark", "/app/data", "/tmp/x")
	if !strings.Contains(out, "当前时间：") {
		t.Fatalf("custom prompt body missing, likely fell back to default: %q", out)
	}
	year := time.Now().Format("2006")
	if !strings.Contains(out, year) {
		t.Fatalf("{{.Now}} did not render the live time (want year %s): %q", year, out)
	}
}

// TestChatDataDirVarRenders verifies the universal {{.DataDir}} runtime variable:
// a custom prompt referencing it renders the server data root (s.m.dir), rather
// than failing template execution and falling back to DefaultAssistantPrompt.
func TestChatDataDirVarRenders(t *testing.T) {
	prev := PromptOverride
	defer func() { PromptOverride = prev }()

	PromptOverride = func(key string) (string, bool) {
		return "数据根目录：{{.DataDir}}", true
	}

	out := chatSystem("tec_benchmark", "/app/data", "/tmp/x")
	if !strings.Contains(out, "数据根目录：/app/data") {
		t.Fatalf("{{.DataDir}} did not render the data root: %q", out)
	}
}

// TestChatUnknownVarFallsBack verifies an out-of-catalog {{.X}} still degrades
// safely to the default assistant prompt (never a half-rendered prompt).
func TestChatUnknownVarFallsBack(t *testing.T) {
	prev := PromptOverride
	defer func() { PromptOverride = prev }()

	PromptOverride = func(key string) (string, bool) {
		return "引用了不存在的变量：{{.Bogus}}", true
	}

	out := chatSystem("whatever", "/app/data", "/tmp/x")
	if strings.Contains(out, "引用了不存在的变量") {
		t.Fatalf("broken template should have fallen back, got custom body: %q", out)
	}
	if !strings.Contains(out, DefaultAssistantPrompt) {
		t.Fatalf("expected fallback to DefaultAssistantPrompt, got: %q", out)
	}
}

source/agent/provider_quota_test.go:
package agent

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/Autumn-27/norma/llm"
)

type roundTripperFunc func(*http.Request) (*http.Response, error)

func (f roundTripperFunc) RoundTrip(req *http.Request) (*http.Response, error) { return f(req) }

func TestIsQuotaExhaustedMessage(t *testing.T) {
	t.Parallel()
	positive := []string{
		`{"error":{"code":"insufficient_quota"}}`,
		`RESOURCE_EXHAUSTED`,
		`You exceeded your current quota, please check your plan and billing details.`,
		`billing_not_active`,
		`credit balance is too low`,
		`账户余额不足，请充值`,
	}
	for _, message := range positive {
		if !IsQuotaExhaustedMessage(message) {
			t.Errorf("expected quota classification for %q", message)
		}
	}

	negative := []string{
		`status 429: rate limit exceeded`,
		`RESOURCE_EXHAUSTED: rate limit exceeded`,
		`too many requests per minute`,
		`quota exceeded for quota metric GenerateRequestsPerMinutePerProjectPerBaseModel`,
		`RESOURCE_EXHAUSTED: TPM quota exceeded`,
		`tokens per minute quota exceeded`,
		`rate_limit_exceeded: requests per second`,
		`status 401: invalid api key`,
		`status 401: insufficient_quota`,
		`HTTP 403: billing_hard_limit_reached`,
		`status 500: internal server error`,
		`status=503: insufficient_quota`,
		`context length exceeded`,
	}
	for _, message := range negative {
		if IsQuotaExhaustedMessage(message) {
			t.Errorf("unexpected quota classification for %q", message)
		}
	}
}

func TestQuotaAwareTransportOnlyNormalizesExplicitQuota429(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name       string
		status     int
		body       string
		wantStatus int
	}{
		{name: "quota", status: http.StatusTooManyRequests, body: `{"code":"insufficient_quota"}`, wantStatus: http.StatusPaymentRequired},
		{name: "ordinary rate limit", status: http.StatusTooManyRequests, body: `{"message":"rate limit exceeded"}`, wantStatus: http.StatusTooManyRequests},
		{name: "server error", status: http.StatusInternalServerError, body: `insufficient_quota`, wantStatus: http.StatusInternalServerError},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			transport := quotaAwareTransport{base: roundTripperFunc(func(*http.Request) (*http.Response, error) {
				return &http.Response{
					StatusCode: tt.status,
					Status:     http.StatusText(tt.status),
					Body:       io.NopCloser(strings.NewReader(tt.body)),
					Header:     make(http.Header),
				}, nil
			})}
			req, err := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.invalid", nil)
			if err != nil {
				t.Fatal(err)
			}
			resp, err := transport.RoundTrip(req)
			if err != nil {
				t.Fatal(err)
			}
			defer resp.Body.Close()
			if resp.StatusCode != tt.wantStatus {
				t.Fatalf("status=%d, want %d", resp.StatusCode, tt.wantStatus)
			}
			gotBody, err := io.ReadAll(resp.Body)
			if err != nil {
				t.Fatal(err)
			}
			if string(gotBody) != tt.body {
				t.Fatalf("body=%q, want %q", gotBody, tt.body)
			}
		})
	}
}

func TestProviderDoesNotRetryExplicitQuota429(t *testing.T) {
	t.Parallel()
	var requests atomic.Int32
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		requests.Add(1)
		w.Header().Set("content-type", "application/json")
		w.WriteHeader(http.StatusTooManyRequests)
		_, _ = io.WriteString(w, `{"error":{"code":"insufficient_quota","message":"You exceeded your current quota"}}`)
	}))
	defer upstream.Close()

	provider, err := ConfigFrom("openai", "test-model", upstream.URL, "test-key", "").NewProvider()
	if err != nil {
		t.Fatal(err)
	}
	var streamErr error
	for _, err := range provider.Stream(context.Background(), llm.CompletionRequest{
		Messages: []llm.Message{llm.UserText("ping")},
	}) {
		if err != nil {
			streamErr = err
		}
	}
	if streamErr == nil || !IsQuotaExhaustedMessage(streamErr.Error()) {
		t.Fatalf("expected explicit quota error, got %v", streamErr)
	}
	if got := requests.Load(); got != 1 {
		t.Fatalf("explicit quota request retried %d times, want exactly one request", got)
	}
}

source/agent/finding_workflow.go:
package agent

import (
	"encoding/json"
	"fmt"

	"github.com/Autumn-27/artex/db"
	actool "github.com/Autumn-27/norma/tool"
)

const findingIDGuidance = "\n\n**Finding ID contract**: finding_id is the independent finding-record ID; finding_node_id is the exploration node ID. The id returned by list_findings / list_task_findings / node_detail / get_task_node_detail remains an exploration node ID; read the independent ID from finding_id in the same result. get_finding_traffic / bind_finding_traffic use the independent finding_id. The legacy update_finding_report finding_id argument still takes finding_node_id. Do not use the number on the first line of report_finding with evidence tools, or guess other numbers after an ID error."

// The server supplies the persisted setting. A missing setting/host is off.
// Consulted at assembly and again on writes so an already-running session
// cannot keep binding after the user switches the feature off.
var FindingTrafficBindingEnabled func() bool

func findingTrafficBindingEnabled() bool {
	return FindingTrafficBindingEnabled != nil && FindingTrafficBindingEnabled()
}

// Applied after ToolResolve: user descriptions and prompts remain intact, while
// all actual reporters (including Planner and custom chat agents) see the same
// API contract. Disabled/unbound tools are never reintroduced here.
func findingWorkflowTools(agentKey string, tools []actool.CoreTool) ([]actool.CoreTool, string) {
	if !findingTrafficBindingEnabled() {
		out := make([]actool.CoreTool, 0, len(tools))
		for _, tool := range tools {
			if tool.Name() == "bind_finding_traffic" {
				continue
			}
			if agentKey == "reporter" && (tool.Name() == "traffic_search" || tool.Name() == "traffic_get" || tool.Name() == "traffic_blob") {
				continue
			}
			switch tool.Name() {
			case "report_finding", "add_hint", "add_task_hint":
				// Work on a copy: toggling back on must restore the original schema.
				raw, _ := json.Marshal(tool.InputSchema())
				var schema map[string]any
				if json.Unmarshal(raw, &schema) == nil {
					stripTrafficParameters(schema)
					tool = DecorateTool(tool, tool.Description(), schema)
				}
			}
			out = append(out, tool)
		}
		return out, ""
	}
	out := append([]actool.CoreTool(nil), tools...)
	has := map[string]bool{}
	for i, tool := range out {
		has[tool.Name()] = true
		note := ""
		switch tool.Name() {
		case "report_finding":
			note = "\nBy default, the reporting agent verifies and binds traffic before writing the report. The reporter should retain verification commands, key output, existing real traffic IDs and their purpose in evidence so the reporting agent can check them against execution traces. Do not query extra packets merely for binding. Explicit immediate binding remains supported: traffic_refs or evidence_hint_id may carry verified references; the latter reads structured references from the specified hint in this task. If any reference is invalid, the entire report_finding call fails. TCP/no-packet cases do not require these optional arguments. Returned finding_id and finding_node_id identify the independent record and exploration node respectively."
		case "add_hint", "add_task_hint":
			note = "\nWhen handing off a confirmed vulnerability, preserve verified traffic IDs, roles, notes, and order in the corresponding hint traffic_refs (top-level for a single hint, in the corresponding hints element for a batch), and describe the specific vulnerability it proves in text. Do not hand off only prose while discarding existing traffic references. Unverified candidates must not be passed as evidence."
		case "get_finding_traffic", "bind_finding_traffic", "list_findings", "list_task_findings", "node_detail", "get_task_node_detail", "update_finding_report":
			note = findingIDGuidance
		}
		if note != "" {
			out[i] = DecorateTool(tool, tool.Description()+note, tool.InputSchema())
		}
	}
	guidance := ""
	if has["report_finding"] || has["add_task_hint"] || has["add_hint"] {
		guidance = "\n\n**Traffic evidence handoff (optional)**: by default, the reporting agent performs automatic binding after the finding is recorded and before writing its report. Retain verification commands, key output, existing real traffic IDs and their purpose in evidence; include intent_id in task context for traceability. Do not query extra packets merely for binding. Auto / Planner reporting on behalf of an executor must retain existing references. add_hint / add_task_hint can hand off traffic_refs; explicit immediate binding remains compatible with report_finding traffic_refs / evidence_hint_id. Record TCP/no-packet cases normally. Never guess IDs or repeat probes solely to obtain packets."
		if has["add_task_hint"] && !has["add_hint"] {
			guidance += "\nFor platform chat without task context, do not call report_finding directly. Hand off to the corresponding existing task with add_task_hint, let its task agent record the finding, and verify the result with list_task_findings."
		}
		if has["prove_goal"] || has["goal_met"] {
			guidance += "\nBefore declaring goals complete, finish reporting/handing off existing evidence from this run. Do not end the task or cancel workers merely because a text finding is recorded while evidence handoff remains incomplete. No-packet cases do not require waiting or forced capture."
		}
	}
	if has["update_finding_report"] && has["bind_finding_traffic"] && has["get_finding_traffic"] {
		guidance += "\n\n**Automatic traffic association before reporting (enabled)**: verify and bind traffic for this triggered finding, then write the report. First obtain explicit finding_id and finding_node_id from report_finding JSON or get_task_node_detail / list_task_findings. Read the finding detail, corresponding intent execution trace, and existing evidence manifest, prioritizing real IDs handed off by the reporter. If verification was HTTP and traffic tools are available, filter candidates with traffic_search and verify each request/response supports the finding with traffic_get; domain and time only filter candidates, not prove ownership. Bind confirmed evidence in reproduction order with bind_finding_traffic(finding_id, traffic_refs), choosing baseline / proof / verification / supporting and explaining its purpose. Operate only on this finding: do not create duplicate findings or probe the target again. After successful binding, reread get_finding_traffic for the latest version, read the required bodies, and pass the version actually read as evidence_version to update_finding_report (whose finding_id still takes finding_node_id). Do not append existing bindings again. For TCP, uncaptured traffic, unavailable tools, or no exact match, skip automatic binding and write normally from text/command evidence, explaining why. Never guess to fill traffic gaps. Do not claim binding succeeded if it failed; retain existing evidence and explain missing bindings in the report."
	}
	if guidance != "" || has["get_finding_traffic"] || has["update_finding_report"] {
		guidance += findingIDGuidance
	}
	return out, guidance
}

func stripTrafficParameters(schema map[string]any) {
	props, _ := schema["properties"].(map[string]any)
	delete(props, "traffic_refs")
	delete(props, "evidence_hint_id")
	if required, ok := schema["required"].([]any); ok {
		kept := required[:0]
		for _, key := range required {
			if key != "traffic_refs" && key != "evidence_hint_id" {
				kept = append(kept, key)
			}
		}
		schema["required"] = kept
	}
	if hints, ok := props["hints"].(map[string]any); ok {
		if items, ok := hints["items"].(map[string]any); ok {
			stripTrafficParameters(items)
		}
	}
}

// HintTrafficSchema is shared by the task-local and cross-task hint tools.
func HintTrafficSchema() map[string]any {
	return map[string]any{"type": "array", "description": "Optional: verified traffic references supporting the specific vulnerability in this hint, preserving order. After handoff, report_finding can carry these references via evidence_hint_id.", "items": obj(map[string]any{"traffic_id": str("Real traffic ID"), "role": str("baseline / proof / verification / supporting"), "note": str("What conclusion this traffic supports")}, "traffic_id")}
}

func (t *ToolSet) findingRefsFromHint(hintID int64, explicit []db.TrafficRef) ([]db.TrafficRef, error) {
	if hintID <= 0 {
		return db.NormalizeTrafficRefs(explicit)
	}
	n, err := t.ts.GetNode(hintID) // local store only: inherited hints cannot supply evidence
	if err != nil {
		return nil, err
	}
	if n == nil || n.Kind != db.KindHint {
		return nil, fmt.Errorf("evidence_hint_id=%d must identify a hint node in this task (inherited hints cannot be used directly for binding)", hintID)
	}
	var payload struct {
		Refs []db.TrafficRef `json:"traffic_refs"`
	}
	if err := json.Unmarshal(n.Payload, &payload); err != nil {
		return nil, err
	}
	return db.NormalizeTrafficRefs(append(append([]db.TrafficRef{}, explicit...), payload.Refs...))
}

source/agent/noa.go:
package agent

import (
	"log"
	"path/filepath"

	"github.com/Autumn-27/norma/agentcore"
	"github.com/Autumn-27/norma/noaadapter"
)

// noaWarn returns a diagnostics sink tagging non-fatal noa messages with the
// session, routed through the package logger (agents have no per-instance one).
func noaWarn(session string) func(string) {
	return func(msg string) { log.Printf("[noa] %s: %s", session, msg) }
}

// noa 是 norma v0.4.0 引入的「模型驱动上下文压缩」机制,作为平台实验功能由用户在
// 系统设置中开关。它与内置 compaction 互斥:noaadapter.Enable 是唯一入口,一次挂上
// 上下文接管器(Compactor)、Compress 工具与三段常驻提示词,不调用 Enable 即为关闭
// (内置 compaction 照常工作)。开关由每个 agent 注入的 noaEnabledFn 解析,每 run 读
// 一次,故切换只影响之后启动的 run,无需重建 agent。

// enableNoa 在解析器报告开启时把 noa 接入 opts。archiveRoot 是压缩原文的持久化基目录
// (取全局 workDir,各 agent 统一落在 <workDir>/noa 下,不随任务/意图目录分散),sessionID
// 命名其下的归档子目录(全局唯一,故同一基目录内不冲突)。
//
// noa 是实验功能:接入失败不得中断真实任务。发生错误时经 onWarn 上报并回退内置压缩。
// 启用成功时清掉 opts.Compaction,避免 agentcore 因「两个上下文管理器同时设置」告警。
func enableNoa(opts *agentcore.Options, enabled func() bool, archiveRoot, sessionID string, onWarn func(string)) {
	if enabled == nil || !enabled() {
		return
	}
	if opts.OnWarn == nil {
		opts.OnWarn = onWarn
	}
	if err := noaadapter.Enable(opts, noaadapter.Options{
		ArchiveBaseDir: filepath.Join(archiveRoot, "noa"),
		SessionID:      sessionID,
		OnWarn:         onWarn,
	}); err != nil {
		if onWarn != nil {
			onWarn("noa 压缩启用失败,回退内置压缩:" + err.Error())
		}
		return
	}
	// Compactor 覆盖 Compaction,但两者并存时 agentcore 每次会告警;明确清掉。
	opts.Compaction = nil
}

source/agent/native_role.go:
package agent

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"regexp"
	"strings"
	"sync"
	"time"

	"github.com/Autumn-27/norma/llm"
	actool "github.com/Autumn-27/norma/tool"
	"github.com/Autumn-27/norma/transcript"
)

// This permit is administrator-owned runtime data, never a Config/API/env value.
// Loading it does not authorize a model call or an effect. Reporter templates
// require a separately SQL-qualified committed finding/conversation event.
type nativePhasePermit struct {
	state             *nativePhaseState
	SchemaVersion     int               `json:"schema_version"`
	PhaseID           string            `json:"phase_id"`
	Generation        int64             `json:"authority_generation"`
	TaskID            int64             `json:"task_id"`
	ExplorationID     int64             `json:"exploration_id"`
	FixtureOrigin     string            `json:"fixture_origin"`
	NetworkPolicyID   string            `json:"network_policy_id"`
	ExecutorID        string            `json:"executor_id"`
	LedgerID          string            `json:"ledger_id"`
	ExpiresAt         time.Time         `json:"expires_at"`
	MaxCalls          int               `json:"max_calls"`
	MaxAggregateBytes int               `json:"max_aggregate_bytes"`
	Roles             []nativePhaseRole `json:"roles"`
}
type nativePhaseRole struct {
	DynamicIntent  bool   `json:"dynamic_intent,omitempty"`
	DynamicFinding bool   `json:"dynamic_finding,omitempty"`
	Role           string `json:"role"`
	Purpose        string `json:"purpose"`
	IntentID       int64  `json:"intent_id"`
	SessionID      string `json:"session_id"`
	CatalogSHA256  string `json:"catalog_sha256"`
}

var nativeDigest = regexp.MustCompile(`^[a-f0-9]{64}$`)

func parseNativePhase(raw []byte) (*nativePhasePermit, error) {
	var p nativePhasePermit
	if strictNativeJSON(raw, &p) != nil {
		return nil, nativeErr
	}
	now := time.Now()
	if p.SchemaVersion != 1 || !nativeName.MatchString(p.PhaseID) || p.Generation <= 0 || p.TaskID <= 0 || p.ExplorationID <= 0 || !nativeName.MatchString(p.NetworkPolicyID) || !nativeName.MatchString(p.ExecutorID) || !nativeName.MatchString(p.LedgerID) || !p.ExpiresAt.After(now) || p.ExpiresAt.After(now.Add(600*time.Second)) || p.MaxCalls < 1 || p.MaxCalls > 16 || p.MaxAggregateBytes < nativeCap || p.MaxAggregateBytes > 2*1024*1024 || len(p.Roles) < 1 || len(p.Roles) > 16 {
		return nil, nativeErr
	}
	u, e := url.Parse(p.FixtureOrigin)
	if e != nil || u.Scheme != "http" || u.Hostname() == "" || u.User != nil || u.Path != "" || u.RawPath != "" || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || u.String() != p.FixtureOrigin {
		return nil, nativeErr
	}
	seen := map[string]bool{}
	for _, r := range p.Roles {
		session := fmt.Sprintf("exp%d-%s", p.ExplorationID, r.Role)
		if r.DynamicFinding && r.Role != "reporter" {
			return nil, nativeErr
		}
		switch r.Role {
		case "goals", "planner", "mainagent":
			if r.DynamicIntent {
				return nil, nativeErr
			}
			if r.IntentID != 0 {
				return nil, nativeErr
			}
			if r.Role == "mainagent" {
				session = fmt.Sprintf("exp%d-main", p.ExplorationID)
			}
		case "reporter":
			if !r.DynamicFinding || r.DynamicIntent || r.IntentID != 0 || r.SessionID != "" {
				return nil, nativeErr
			}
			session = "reporter-template"
		case "worker":
			if r.DynamicIntent {
				if r.IntentID != 0 || r.SessionID != "" {
					return nil, nativeErr
				}
				session = ""
			} else {
				if r.IntentID <= 0 {
					return nil, nativeErr
				}
				session = fmt.Sprintf("exp%d-worker-i%d", p.ExplorationID, r.IntentID)
			}
		default:
			return nil, nativeErr
		}
		if r.Purpose != "run" || (r.Role != "reporter" && r.SessionID != session) || !nativeDigest.MatchString(r.CatalogSHA256) || seen[session] {
			return nil, nativeErr
		}
		seen[session] = true
	}
	// Process-local defense only. The independent broker remains responsible for
	// durable reservations and sealing on restart; this does not replace its ledger.
	canonical, e := json.Marshal(p)
	if e != nil {
		return nil, nativeErr
	}
	digest := sha256.Sum256(canonical)
	key := fmt.Sprintf("%s/%d", p.PhaseID, p.Generation)
	nativePhaseStates.Lock()
	defer nativePhaseStates.Unlock()
	if old := nativePhaseStates.states[key]; old != nil {
		if old.digest != digest {
			return nil, nativeErr
		}
		p.state = old
	} else {
		phaseCtx, cancel := context.WithCancel(context.Background())
		p.state = &nativePhaseState{digest: digest, ctx: phaseCtx, cancel: cancel}
		nativePhaseStates.states[key] = p.state
	}
	return &p, nil
}

type nativePhaseState struct {
	mu                   sync.Mutex
	digest               [32]byte
	calls, reservedBytes int
	inFlight, stopped    bool
	flightDone           chan struct{}
	ctx                  context.Context
	cancel               context.CancelFunc
}

var nativePhaseStates = struct {
	sync.Mutex
	states map[string]*nativePhaseState
}{states: map[string]*nativePhaseState{}}

type nativeRoleAdmissionKey struct{}
type nativeRoleAdmission struct {
	state *nativePhaseState
	role  nativePhaseRole
	run   RunInfo
}

// BindNativeRole is a trusted Go-host boundary, not a request/RunInfo authority
// parser. The private permit must already name this exact run and final catalog.
// Normal role launchers must validate DB membership and disable SDK support
// before calling it. Neither a chat marker nor arbitrary RunInfo grants access.
func (p *nativeRPC) BindNativeRole(ctx context.Context, role, purpose string, ri RunInfo, tools []llm.ToolSchema) (context.Context, error) {
	phase := p.policy.phase
	if phase == nil || phase.state == nil || ctx.Err() != nil || !time.Now().Before(phase.ExpiresAt) || ri.TaskID != phase.TaskID || ri.ExplorationID != phase.ExplorationID || ri.SessionID != "" || RunInfoFrom(ctx) != ri {
		return nil, nativeErr
	}
	phase.state.mu.Lock()
	stopped := phase.state.stopped
	phase.state.mu.Unlock()
	if stopped {
		return nil, nativeErr
	}
	session := transcript.SessionIDFrom(ctx)
	for _, r := range phase.Roles {
		if r.DynamicFinding {
			continue
		}
		if r.Role == role && r.Purpose == purpose && r.IntentID == ri.IntentID && r.SessionID == session {
			fingerprint, e := nativeRoleCatalog(phase, r, tools)
			if e != nil || fingerprint != r.CatalogSHA256 {
				return nil, nativeErr
			}
			return context.WithValue(ctx, nativeRoleAdmissionKey{}, nativeRoleAdmission{phase.state, r, ri}), nil
		}
	}
	return nil, nativeErr
}

func (p *nativeRPC) RevokeNativeRolePhase() {
	if phase := p.policy.phase; phase != nil && phase.state != nil {
		phase.state.mu.Lock()
		phase.state.stopped = true
		phase.state.cancel()
		phase.state.mu.Unlock()
	}
}

func nativeRoleToolNames(role string) string {
	allowed := map[string]string{
		"reporter":  "get_task_node_detail node_detail get_finding_traffic update_finding_report",
		"goals":     "set_goals set_constraints",
		"planner":   "graph_overview list_findings list_facts node_detail get_worker_output get_worker_trace search_all_worker_traces list_goals add_intent prove_goal kill_work steer_work",
		"worker":    "report_finding list_findings record_fact node_detail get_worker_trace search_all_worker_traces Read Write Edit LS Bash sleep",
		"mainagent": "graph_overview list_findings list_facts node_detail get_worker_output get_worker_trace search_all_worker_traces add_hint add_intent steer_work record_fact",
	}
	return allowed[role]
}
func nativeRoleAllows(role, name string) bool {
	return strings.Contains(" "+nativeRoleToolNames(role)+" ", " "+name+" ") && name != ""
}
func nativeRoleCatalog(phase *nativePhasePermit, role nativePhaseRole, tools []llm.ToolSchema) (string, error) {
	if len(tools) < 1 || len(tools) > 32 || nativeRoleToolNames(role.Role) == "" {
		return "", nativeErr
	}
	seen := map[string]bool{}
	for _, t := range tools {
		if seen[t.Name] || !nativeRoleAllows(role.Role, t.Name) || t.InputSchema["type"] != "object" {
			return "", nativeErr
		}
		seen[t.Name] = true
	}
	raw, e := json.Marshal(map[string]any{"role": role.Role, "purpose": role.Purpose, "executor_id": phase.ExecutorID, "network_policy_id": phase.NetworkPolicyID, "tools": tools})
	if e != nil || len(raw) > nativeCap {
		return "", nativeErr
	}
	h := sha256.Sum256(raw)
	return hex.EncodeToString(h[:]), nil
}

func (p *nativeRPC) validateNativeRole(ctx context.Context, r llm.CompletionRequest) bool {
	phase := p.policy.phase
	a, ok := ctx.Value(nativeRoleAdmissionKey{}).(nativeRoleAdmission)
	if phase == nil || !ok || a.state != phase.state || ctx.Err() != nil || !time.Now().Before(phase.ExpiresAt) || RunInfoFrom(ctx) != a.run || transcript.SessionIDFrom(ctx) != a.role.SessionID {
		return false
	}
	if scope, scoped := ctx.Value(nativeTaskScopeKey{}).(nativeTaskScope); scoped {
		if scope.role == "reporter" {
			event, ok := ctx.Value(nativeFindingKey{}).(nativeFindingAuthority)
			if !ok || event.validate(ctx) != nil {
				return false
			}
		}
		if scope.validate != nil {
			if scope.validate(ctx, "") != nil {
				return false
			}
			for _, t := range r.Tools {
				if scope.validate(ctx, t.Name) != nil {
					return false
				}
			}
		}
		if scope.provider != p || scope.run != a.run || scope.role != a.role.Role || checkNativeTaskMembership(scope.store, scope.run, scope.role) != nil {
			return false
		}
		if scope.validate != nil {
			// Resample the same normal factories/resolver, including DB metadata
			// overrides, after queueing and immediately before HTTP. No authority
			// is minted by schema derivation; the original sealed digest wins.
			reporter := []actool.CoreTool{ReporterNodeTool(nil), ReporterTrafficTool(nil), ReporterUpdateTool(nil)}
			_, current, e := NativePreflightCatalog(ctx, scope.role, phase.ExecutorID, phase.NetworkPolicyID, scope.store, scope.run.TaskID, reporter, scope.reportingReady, ToolResolve)
			if e != nil || current != a.role.CatalogSHA256 {
				return false
			}
		}
	}
	phase.state.mu.Lock()
	stopped := phase.state.stopped
	phase.state.mu.Unlock()
	if stopped {
		return false
	}
	hash, e := nativeRoleCatalog(phase, a.role, r.Tools)
	return e == nil && hash == a.role.CatalogSHA256
}

// Reserve pessimistically for the maximum response. Failed/lost responses never
// refund attempts or bytes. Capacity is separate and released after IO settles.
func (p *nativeRPC) reserveNativeRole(ctx context.Context, size int, request llm.CompletionRequest) (func(), bool) {
	phase := p.policy.phase
	if phase == nil {
		return func() {}, true
	}
	s := phase.state
	for {
		// Revalidate live source/DB membership and exact sealed catalog after every
		// wait, before charging any attempt. Never hold phase mutex during SQL or wait.
		if !p.validateNativeRole(ctx, request) {
			return nil, false
		}
		s.mu.Lock()
		if s.stopped || ctx.Err() != nil || !time.Now().Before(phase.ExpiresAt) {
			s.mu.Unlock()
			return nil, false
		}
		if s.inFlight {
			done := s.flightDone
			s.mu.Unlock()
			select {
			case <-done:
			case <-ctx.Done():
				return nil, false
			case <-s.ctx.Done():
				return nil, false
			}
			continue
		}
		if s.calls >= phase.MaxCalls || p.calls >= p.policy.MaxCalls || size+nativeCap > phase.MaxAggregateBytes-s.reservedBytes {
			s.mu.Unlock()
			return nil, false
		}
		s.calls++
		s.reservedBytes += size + nativeCap
		p.calls++
		s.inFlight = true
		s.flightDone = make(chan struct{})
		done := s.flightDone
		s.mu.Unlock()
		return func() { s.mu.Lock(); s.inFlight = false; close(done); s.mu.Unlock() }, true
	}
}

// encoding/json alone accepts duplicate object keys. Reject them recursively
// before decoding the exact typed schema; no coercion or unknown fields.
func strictNativeJSON(raw []byte, out any) error {
	d := json.NewDecoder(bytes.NewReader(raw))
	d.UseNumber()
	var value func() error
	value = func() error {
		tok, e := d.Token()
		if e != nil {
			return e
		}
		delim, ok := tok.(json.Delim)
		if !ok {
			return nil
		}
		switch delim {
		case '{':
			seen := map[string]bool{}
			for d.More() {
				k, e := d.Token()
				if e != nil {
					return e
				}
				s, ok := k.(string)
				if !ok || seen[s] {
					return nativeErr
				}
				seen[s] = true
				if e = value(); e != nil {
					return e
				}
			}
			end, e := d.Token()
			if e != nil || end != json.Delim('}') {
				return nativeErr
			}
		case '[':
			for d.More() {
				if e := value(); e != nil {
					return e
				}
			}
			end, e := d.Token()
			if e != nil || end != json.Delim(']') {
				return nativeErr
			}
		default:
			return nativeErr
		}
		return nil
	}
	if e := value(); e != nil {
		return e
	}
	if _, e := d.Token(); e != io.EOF {
		return nativeErr
	}
	d = json.NewDecoder(bytes.NewReader(raw))
	d.DisallowUnknownFields()
	if e := d.Decode(out); e != nil {
		return e
	}
	if d.Decode(new(any)) != io.EOF {
		return nativeErr
	}
	return nil
}

