package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/artex/guard"
	"github.com/Autumn-27/artex/intercept"
	"github.com/Autumn-27/norma/llm"
	"github.com/Autumn-27/norma/tool"
)

// Real PostgreSQL + SDK hooks: Worker reviews receive the current call only.
// Intent summaries, inherited background and prior execution are excluded.
func TestWorkerReviewContextAcrossToolCalls(t *testing.T) {
	dsn, _, err := db.DSN()
	if err != nil {
		t.Skip("no test database configured")
	}
	d, err := db.Open(dsn)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = d.Close() })
	expID, err := d.CreateExploration("只操作隔离测试目录", "验证创建和清理")
	if err != nil {
		t.Fatal(err)
	}
	ts := d.Exploration(expID)
	taskID := fmt.Sprint(expID)
	t.Cleanup(func() {
		_, _ = d.Exec(`DELETE FROM intercept_pending WHERE task_id=$1`, taskID)
		_, _ = d.Exec(`DELETE FROM explorations WHERE id=$1`, expID)
	})
	ic := intercept.New(d)
	priorTools, err := ic.GetEnabledTools()
	if err != nil {
		t.Fatal(err)
	}
	priorConfig := ic.GetJudgeConfig()
	t.Cleanup(func() { _ = ic.SetEnabledTools(priorTools); _ = ic.SetJudgeConfig(priorConfig) })
	const probeName = "ContextEvidenceProbe"
	if err := ic.SetEnabledTools([]string{probeName}); err != nil {
		t.Fatal(err)
	}
	if err := ic.SetJudgeConfig(intercept.JudgeConfig{Enabled: true}); err != nil {
		t.Fatal(err)
	}
	var inputs []intercept.ReviewInput
	ic.SetReviewer(func(_ context.Context, _ int64, _ string, in intercept.ReviewInput) (intercept.Decision, error) {
		inputs = append(inputs, in)
		action := "allow"
		if string(in.Arguments) == `{"step":2}` {
			action = "deny"
		}
		return intercept.Decision{Action: action, Message: "probe policy"}, nil
	})
	turn, executions := 0, 0
	provider := captureUsageProvider{stream: func(_ context.Context, yield func(llm.StreamEvent, error) bool) {
		turn++
		events := []llm.StreamEvent{{Type: llm.SETextDelta, Text: "done"}, {Type: llm.SEMessageDelta, StopReason: "end_turn"}}
		if turn <= 2 {
			events = []llm.StreamEvent{
				{Type: llm.SEToolUseStart, ToolID: fmt.Sprintf("call-%d", turn), ToolName: probeName},
				{Type: llm.SEToolInputJSON, Text: fmt.Sprintf(`{"step":%d}`, turn)},
				{Type: llm.SEMessageDelta, StopReason: "tool_use"},
			}
		}
		for _, event := range events {
			if !yield(event, nil) {
				return
			}
		}
	}}
	probe := tool.Build(tool.Spec{Name: probeName, Schema: map[string]any{"type": "object"},
		Run: func(context.Context, json.RawMessage, *tool.ToolContext) (tool.Result, error) {
			executions++
			_, err := ts.AddConstraint("deny", "禁止后续清理", "human")
			return tool.Text("Created a new fixture; no existing file overwritten."), err
		},
	})
	workDir := t.TempDir()
	ctx := intercept.WithTaskContext(t.Context(), taskID, "test-agent", nil)
	ctx = intercept.WithReviewContext(ctx, "/parent", intercept.ReviewBackground{Source: intercept.BackgroundUserMessage, Text: "PARENT_BACKGROUND_SENTINEL"})
	intentPayload := map[string]any{"summary": "创建并清理", "extra": "FULL_INTENT_SENTINEL"}
	intentID, err := ts.AddNode("intent", intentPayload, 0, "running", "planner", nil)
	if err != nil {
		t.Fatal(err)
	}
	rawIntent, _ := json.Marshal(intentPayload)
	worker := NewWorker(provider, "test-model", workDir, nil, 0, 3, probe)
	_, _, err = worker.Execute(ctx, "test-agent", expID, nil, ts, &db.Node{ID: intentID, Payload: rawIntent}, guard.NewWithInterceptor(ic).Hooks(), nil, nil, nil)
	runDir := ensureRunDir(workDir, expID, intentID)
	if err != nil {
		t.Fatal(err)
	}
	if len(inputs) != 2 || executions != 1 {
		t.Fatalf("reviews=%d executions=%d", len(inputs), executions)
	}
	first, second := inputs[0], inputs[1]
	for _, in := range inputs {
		if in.Version != 4 || in.Background != nil || in.WorkingDir != runDir {
			t.Fatalf("unexpected Worker background: %+v", in)
		}
		raw, _ := json.Marshal(in)
		for _, forbidden := range []string{"创建并清理", "PARENT_BACKGROUND_SENTINEL", `"background"`, "只操作隔离测试目录", "验证创建和清理", "禁止后续清理", "FULL_INTENT_SENTINEL", "全局探索态势", `"task_id"`, `"task"`, `"turn_input"`, `"worker_intent"`, `"history"`, `"history_truncated"`, `"correlation"`, "Created a new fixture"} {
			if strings.Contains(string(raw), forbidden) {
				t.Fatalf("unexpected review data: %s", forbidden)
			}
		}
	}
	constraints, err := ts.ListConstraints()
	if err != nil || len(constraints) != 1 {
		t.Fatal("Agent task constraints were unexpectedly changed")
	}
	if string(first.Arguments) != `{"step":1}` || string(second.Arguments) != `{"step":2}` {
		t.Fatal("review lost current parameters")
	}

	rows, err := d.ListTaskIntercepts(taskID)
	if err != nil || len(rows) != 2 {
		t.Fatalf("rows=%d err=%v", len(rows), err)
	}
	for _, row := range rows {
		detail, err := d.GetInterceptDetail(row.ID)
		if err != nil || detail == nil || detail.Audit == nil || len(detail.Audit.ModelInput) == 0 {
			t.Fatalf("verdict lost model input: %+v err=%v", detail, err)
		}
		var saved intercept.ReviewInput
		if json.Unmarshal(detail.Audit.ModelInput, &saved) != nil || saved.Background != nil || saved.Version != 4 {
			t.Fatal("stored Worker review input retained a background")
		}
		if row.Status == "allowed" && (detail.Audit.ExecutionStatus != "succeeded" || saved.Version != 4) {
			t.Fatal("automatic allow lost execution result or its original background snapshot")
		}
		if detail.Audit.Correlation != "exact" {
			t.Fatal("audit lost call correlation")
		}
		if row.Status == "denied" {
			found := false
			for _, entry := range detail.Audit.Context {
				if entry.Kind == "tool_result" && entry.ToolUseID == "call-1" && strings.Contains(entry.Text, "Created a new fixture") {
					found = true
				}
			}
			if !found {
				t.Fatal("prior execution missing from separate audit")
			}
		}
		if row.Status == "denied" && detail.Audit.ExecutionStatus != "not_executed" {
			t.Fatal("denial recorded an execution")
		}
	}

}

source/agent/native_admission.go:
package agent

// Initial private owned-sink lab only; ARTEX/Norma remain the agent and executor.
import (
	"bytes"
	"context"
	"encoding/json"
	actool "github.com/Autumn-27/norma/tool"
	"io"
	"net/url"
	"os"
	"regexp"
	"syscall"
	"time"
)

type nativePolicyDocument struct {
	Model                    string `json:"model"`
	Protocol                 string `json:"protocol"`
	Endpoint                 string `json:"endpoint"`
	BudgetMode               string `json:"budget_mode"`
	TimeoutSeconds           int    `json:"timeout_seconds"`
	MaxCalls                 int    `json:"max_calls"`
	MaxBytes                 int    `json:"max_bytes"`
	GenerationTokensEnforced *bool  `json:"generation_tokens_enforced"`
	NativeTools              *bool  `json:"native_tools"`
	Streaming                *bool  `json:"streaming"`
	RolePhaseEnabled         bool   `json:"role_phase_enabled"`
}

const nativeRuntimeDir = "/run/artex-native"
const nativeCurl = "/usr/bin/curl -q --noproxy '*' --proxy '' --fail --silent --show-error --max-time 10 --max-filesize 4096 --proto '=http' -- http://artex-owned-sink:8080/nonce"

func nativeEndpoint(endpoint string) bool {
	u, e := url.Parse(endpoint)
	return e == nil && u.Scheme == "http" && u.User == nil && u.RawQuery == "" && !u.ForceQuery && u.Fragment == "" && u.RawPath == "" && u.Path == "/artex/native/v1/complete" && ((u.Hostname() == "127.0.0.1" && regexp.MustCompile(`^[1-9][0-9]{0,4}$`).MatchString(u.Port())) || u.Host == "172.29.88.1:18761")
}
func privateNativeOwner(uid uint32, mode os.FileMode) bool {
	return (uid == 0 || uid == uint32(os.Geteuid())) && mode.Perm() == 0600
}

// The fixed /run parent is trusted root-owned runtime storage. No API/env path selection.
func loadNativePolicy(dir string) (*NativeRPCPolicy, error) {
	return loadNativePolicyForConfig(dir, Config{Model: "gpt-6.1-sol"}, syscall.Openat)
}

// Keep a verified directory descriptor through policy admission and key open.
// openAt is a private test seam; production always passes syscall.Openat.
func loadNativePolicyForConfig(dir string, c Config, openAt func(int, string, int, uint32) (int, error)) (*NativeRPCPolicy, error) {
	if c.Native != nil || c.Stream || c.MaxTokens != 0 || c.MaxTokensField != "" || c.APIKey != "" || c.Proxy != "" || c.Model != "gpt-6.1-sol" || c.ThinkingType != "" || c.ReasoningEffort != "" || c.SessionHeaderKey != "" {
		return nil, nativeErr
	}
	if c.BaseURL != "" && !nativeEndpoint(c.BaseURL) {
		return nil, nativeErr
	}
	fd, e := syscall.Open(dir, syscall.O_RDONLY|syscall.O_DIRECTORY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0)
	if e != nil {
		return nil, nativeErr
	}
	defer syscall.Close(fd)
	var st syscall.Stat_t
	if syscall.Fstat(fd, &st) != nil || (st.Uid != 0 && st.Uid != uint32(os.Geteuid())) || st.Mode&0077 != 0 {
		return nil, nativeErr
	}
	read := func(name string, limit int64) ([]byte, error) {
		n, e := openAt(fd, name, syscall.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK|syscall.O_CLOEXEC, 0)
		if e != nil {
			return nil, nativeErr
		}
		f := os.NewFile(uintptr(n), name)
		defer f.Close()
		info, e := f.Stat()
		if e != nil || !info.Mode().IsRegular() {
			return nil, nativeErr
		}
		s, ok := info.Sys().(*syscall.Stat_t)
		if !ok || !privateNativeOwner(s.Uid, info.Mode()) {
			return nil, nativeErr
		}
		b, e := io.ReadAll(io.LimitReader(f, limit+1))
		if e != nil || int64(len(b)) > limit {
			return nil, nativeErr
		}
		return b, nil
	}
	b, e := read("policy.json", 4096)
	if e != nil {
		return nil, nativeErr
	}
	var p nativePolicyDocument
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.DisallowUnknownFields()
	if dec.Decode(&p) != nil || dec.Decode(new(any)) != io.EOF || p.Model != "gpt-6.1-sol" || p.Protocol != "artex-native-v1" || p.BudgetMode != "time/bytes/calls" || p.TimeoutSeconds < 1 || p.TimeoutSeconds > 90 || p.MaxCalls < 1 || p.MaxCalls > 16 || p.MaxBytes != nativeCap || p.GenerationTokensEnforced == nil || *p.GenerationTokensEnforced || p.NativeTools == nil || *p.NativeTools || p.Streaming == nil || *p.Streaming || !nativeEndpoint(p.Endpoint) {
		return nil, nativeErr
	}
	if c.BaseURL != "" && c.BaseURL != p.Endpoint {
		return nil, nativeErr
	}
	var phase *nativePhasePermit
	if p.RolePhaseEnabled {
		raw, err := read("phase.json", 16384)
		if err != nil {
			return nil, nativeErr
		}
		phase, err = parseNativePhase(raw)
		if err != nil {
			return nil, nativeErr
		}
	}
	// Dedicated broker key is read ONLY after all settings and the policy match.
	key, e := read("service.key", 64)
	if e != nil || !regexp.MustCompile(`^[a-f0-9]{64}$`).Match(key) {
		return nil, nativeErr
	}
	return &NativeRPCPolicy{runtimeDir: dir, phase: phase, Endpoint: p.Endpoint, ServiceKey: string(key), BudgetMode: p.BudgetMode, Timeout: time.Duration(p.TimeoutSeconds) * time.Second, MaxCalls: p.MaxCalls}, nil
}

func (c Config) admittedNativeProvider() (*nativeRPC, error) {
	// In-memory/JSON/DB policy is never authority. Production always uses fixed runtime storage.
	p, e := loadNativePolicyForConfig(nativeRuntimeDir, c, syscall.Openat)
	if e != nil {
		return nil, nativeErr
	}
	c.Native = p
	c.BaseURL = p.Endpoint
	pRPC, e := newNativeRPC(c)
	if e != nil {
		return nil, e
	}
	pRPC.appAdmission = true
	return pRPC, nil
}

type nativeChatContextKey struct{}

type nativeBashTool struct {
	actool.CoreTool
	dir string
}

func nativeBash(t actool.CoreTool, dir string) actool.CoreTool { return &nativeBashTool{t, dir} }
func nativeLabTools(dir string) []actool.CoreTool {
	return []actool.CoreTool{nativeBash(actool.NewBash(), dir)}
}
func (t *nativeBashTool) Description() string {
	return "Limited owned-sink lab: fetch the public nonce using the one exact permitted command."
}
func (t *nativeBashTool) Prompt() string {
	return "Only accepted arguments: command = " + nativeCurl + "; timeout_ms = 10000. No other fields."
}
func (t *nativeBashTool) InputSchema() map[string]any {
	return map[string]any{"type": "object", "properties": map[string]any{"command": map[string]any{"type": "string", "enum": []string{nativeCurl}}, "timeout_ms": map[string]any{"type": "integer", "enum": []int{10000}}}, "required": []string{"command", "timeout_ms"}, "additionalProperties": false}
}
func (t *nativeBashTool) Call(ctx context.Context, raw json.RawMessage, tc *actool.ToolContext) (actool.Result, error) {
	// Byte-exact canonical JSON prevents duplicate keys, coercions, and additional execution fields.
	canonical, _ := json.Marshal(map[string]any{"command": nativeCurl, "timeout_ms": 10000})
	var compact bytes.Buffer
	if json.Compact(&compact, raw) != nil || !bytes.Equal(compact.Bytes(), canonical) || tc == nil || tc.WorkingDir != t.dir {
		return actool.Result{}, nativeErr
	}
	info, e := os.Lstat(t.dir)
	if e != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || info.Mode().Perm()&0077 != 0 {
		return actool.Result{}, nativeErr
	}
	s, ok := info.Sys().(*syscall.Stat_t)
	if !ok || (s.Uid != 0 && s.Uid != uint32(os.Geteuid())) {
		return actool.Result{}, nativeErr
	}
	local := *tc
	local.Tasks = nil
	local.Env = nil
	local.OutputDir = ""
	return t.CoreTool.Call(ctx, raw, &local)
}

source/agent/native_reporter.go:
package agent

import (
	"context"
	"fmt"
	"time"

	"github.com/Autumn-27/artex/db"
	"github.com/Autumn-27/norma/llm"
	"github.com/Autumn-27/norma/transcript"
)

type nativeFindingKey struct{}
type nativeFindingAuthority struct {
	pg                                                              *db.DB
	task, exploration, intent, finding, node, conversation, version int64
}

// WithNativeReporterFinding is a trusted scheduler boundary. Identity comes from
// committed SQL rows, never a tool-result string, prompt, chat marker or RunInfo.
// A fresh conversation is bound to exactly one committed finding and intent.
func WithNativeReporterFinding(ctx context.Context, pg *db.DB, taskID, nodeID, conversationID int64) (context.Context, error) {
	if pg == nil || ctx.Err() != nil || taskID <= 0 || nodeID <= 0 || conversationID <= 0 {
		return nil, nativeErr
	}
	id, e := pg.FindingIDByNodeID(nodeID)
	if e != nil {
		return nil, nativeErr
	}
	f, e := pg.GetFinding(id)
	if e != nil || f == nil || f.TaskID == nil || f.NodeID == nil || *f.TaskID != taskID || *f.NodeID != nodeID {
		return nil, nativeErr
	}
	task, e := pg.GetTask(taskID)
	if e != nil || task == nil {
		return nil, nativeErr
	}
	a := nativeFindingAuthority{pg: pg, task: taskID, exploration: task.ExplorationID, finding: id, node: nodeID, conversation: conversationID, version: f.EvidenceVersion}
	var count int
	e = pg.QueryRow(`SELECT count(*),COALESCE(min(n.id),0) FROM exploration_edges e JOIN exploration_nodes n ON n.id=e.src_id AND n.exploration_id=e.exploration_id WHERE e.exploration_id=$1 AND e.dst_id=$2 AND e.rel='yields' AND n.kind='intent'`, a.exploration, nodeID).Scan(&count, &a.intent)
	if e != nil || count != 1 || a.validate(ctx) != nil {
		return nil, nativeErr
	}
	return context.WithValue(ctx, nativeFindingKey{}, a), nil
}
func (a nativeFindingAuthority) validate(ctx context.Context) error {
	if ctx.Err() != nil || a.pg == nil {
		return nativeErr
	}
	task, e := a.pg.GetTask(a.task)
	if e != nil || task == nil || task.ExplorationID != a.exploration || task.Status != "running" || task.Paused {
		return nativeErr
	}
	conv, e := a.pg.GetConversation(a.conversation)
	if e != nil || conv == nil || conv.AgentKey != "reporter" {
		return nativeErr
	}
	f, e := a.pg.GetFinding(a.finding)
	if e != nil || f == nil || f.TaskID == nil || f.NodeID == nil || *f.TaskID != a.task || *f.NodeID != a.node || f.EvidenceVersion != a.version {
		return nativeErr
	}
	ts := a.pg.Exploration(a.exploration)
	n, e := ts.GetNode(a.node)
	if e != nil || n == nil || n.Kind != db.KindFinding {
		return nativeErr
	}
	n, e = ts.GetNode(a.intent)
	if e != nil || n == nil || n.Kind != db.KindIntent {
		return nativeErr
	}
	var count int
	if a.pg.QueryRow(`SELECT count(*) FROM exploration_edges WHERE exploration_id=$1 AND src_id=$2 AND dst_id=$3 AND rel='yields'`, a.exploration, a.intent, a.node).Scan(&count) != nil || count != 1 {
		return nativeErr
	}
	return nil
}
func HasNativeReporterFinding(ctx context.Context) bool {
	_, ok := ctx.Value(nativeFindingKey{}).(nativeFindingAuthority)
	return ok
}
func (p *nativeRPC) bindNativeReporter(ctx context.Context, ri RunInfo, tools []llm.ToolSchema) (context.Context, error) {
	event, ok := ctx.Value(nativeFindingKey{}).(nativeFindingAuthority)
	phase := p.policy.phase
	if !ok || event.validate(ctx) != nil || phase == nil || phase.state == nil || ri.TaskID != event.task || ri.ExplorationID != event.exploration || ri.IntentID != event.intent || !time.Now().Before(phase.ExpiresAt) || RunInfoFrom(ctx) != ri || transcript.SessionIDFrom(ctx) != fmt.Sprintf("conv-%d", event.conversation) {
		return nil, nativeErr
	}
	for _, r := range phase.Roles {
		if r.Role == "reporter" && r.DynamicFinding {
			hash, e := nativeRoleCatalog(phase, r, tools)
			if e != nil || hash != r.CatalogSHA256 {
				return nil, nativeErr
			}
			r.DynamicFinding = false
			r.IntentID = event.intent
			r.SessionID = fmt.Sprintf("conv-%d", event.conversation)
			ctx = context.WithValue(ctx, nativeRoleAdmissionKey{}, nativeRoleAdmission{phase.state, r, ri})
			if !p.validateNativeRole(ctx, llm.CompletionRequest{Tools: tools}) {
				return nil, nativeErr
			}
			return ctx, nil
		}
	}
	return nil, nativeErr
}
func nativeReporterTemplate(p *nativeRPC) bool {
	if p == nil || p.policy.phase == nil {
		return false
	}
	for _, r := range p.policy.phase.Roles {
		if r.Role == "reporter" && r.DynamicFinding {
			return true
		}
	}
	return false
}

// ValidateNativeDomainInput is shared by original server domain handlers, after
// decoration/defaults. It does not itself grant authority.
func ValidateNativeDomainInput(ctx context.Context, name string, schema map[string]any, raw []byte) error {
	return nativeDomainInput(ctx, name, schema, raw)
}

func NativeReporterTaskID(ctx context.Context) (int64, bool) {
	a, ok := ctx.Value(nativeFindingKey{}).(nativeFindingAuthority)
	return a.task, ok
}

